   "text": "設 \\$C 為一表面面積是 $A\\text{ m}^2$ 的罐的緊漆成本。已知 \\$C 為兩部分之和，一部分為常數，而另一部分隨 $A$ 正變。當 $A=2$ 時，\\$C $= 62$；當 $A=6$ 時，\\$C $= 74$。\n\n(a)　求一表面面積是 $13\\text{ m}^2$ 的罐的緊漆成本。（4 分）\n\n(b)　有一較大的罐與 (a) 所描述的罐相似。若該較大的罐的體積為 (a) 所描述的罐的 8 倍，求該較大的罐的緊漆成本。（2 分）",
