   "html": "<p>$$\\frac{m^{-12}n^8}{n^3}=m^{-12}n^{8-3}$$　<strong>【1M】</strong>（for $\\dfrac{a^p}{a^q}=a^{p-q}$）</p>\n<p>$$=\\frac{n^5}{m^{12}}$$　<strong>【1M+1A】</strong>（1M for $a^{-p}=\\dfrac{1}{a^p}$）</p>\n<p><strong>（3 分）</strong></p>",
