   "text": "> 圖：$y=a(x+b)^2$ 開口向下，頂點位於 $x$ 軸上、原點右側。\n\n開口向下 → $a<0$。\n\n頂點位於 $x=-b$，在正 $x$ 軸上 → $-b>0 \\Rightarrow b<0$。\n\n**答案：D　$a<0$ 且 $b<0$**",
   "html": "<blockquote>\n<p>圖：$y=a(x+b)^2$ 開口向下，頂點位於 $x$ 軸上、原點右側。</p>\n</blockquote>\n<p>開口向下 → $a&lt;0$。</p>\n<p>頂點位於 $x=-b$，在正 $x$ 軸上 → $-b&gt;0 \\Rightarrow b&lt;0$。</p>\n<p><strong>答案：D　$a&lt;0$ 且 $b&lt;0$</strong></p>",
