   "text": "公司中 37.5% 員工為女性（即 3/8，男性 5/8）；60% 男性及 80% 女性已婚，求已婚員工百分比。\n\n$$\\frac{5}{8}\\times 60\\% + \\frac{3}{8}\\times 80\\% = 37.5\\% + 30\\% = 67.5\\%$$\n\n**答案：D　67.5%**",
