   "text": "$x,y$ 為非零數且 $\\dfrac{6x+5y}{3y-2x}=7$，求 $x:y$。\n\n$$6x+5y = 7(3y-2x)$$\n\n$$6x+5y = 21y-14x \\;\\Rightarrow\\; 20x = 16y \\;\\Rightarrow\\; x:y = 4:5$$\n\n**答案：A　$4:5$**",
   "html": "<p>$x,y$ 為非零數且 $\\dfrac{6x+5y}{3y-2x}=7$，求 $x:y$。</p>\n<p>$$6x+5y = 7(3y-2x)$$</p>\n<p>$$6x+5y = 21y-14x \\;\\Rightarrow\\; 20x = 16y \\;\\Rightarrow\\; x:y = 4:5$$</p>\n<p><strong>答案：A　$4:5$</strong></p>",
