   "text": "判斷 $0.0322515$ 的四個舍入陳述哪個正確。\n\n- 3 位有效數字：$0.0322515 \\to 0.0323$（A 錯）\n- 4 位小數：$0.0322|515 \\to 0.0323$（B 錯）\n- 5 位有效數字：$0.03225|15 \\to 0.032252$（C 錯：$0.03225$ 只有 4 個有效數字）\n- 6 位小數：$0.032251|5 \\to 0.032252$（**D 正確**）\n\n**答案：D**",
   "html": "<p>判斷 $0.0322515$ 的四個舍入陳述哪個正確。</p>\n<ul>\n<li>3 位有效數字：$0.0322515 \\to 0.0323$（A 錯）</li>\n<li>4 位小數：$0.0322|515 \\to 0.0323$（B 錯）</li>\n<li>5 位有效數字：$0.03225|15 \\to 0.032252$（C 錯：$0.03225$ 只有 4 個有效數字）</li>\n<li>6 位小數：$0.032251|5 \\to 0.032252$（<strong>D 正確</strong>）</li>\n</ul>\n<p><strong>答案：D</strong></p>",
