   "text": "> 圖：$OAB$、$OCD$ 為同圓心、同圓心角的兩扇形。$\\overset{\\frown}{AB}=12\\pi$ cm、$\\overset{\\frown}{CD}=16\\pi$ cm、$OA=30$ cm。\n\n弧長與半徑成正比：\n\n$$\\frac{OC}{OA} = \\frac{16\\pi}{12\\pi} \\;\\Rightarrow\\; OC = 30\\times\\frac{16}{12} = 40$$\n\n$$AC = OC-OA = 10\\text{ cm}$$\n\n**答案：B　10 cm**",
   "html": "<blockquote>\n<p>圖：$OAB$、$OCD$ 為同圓心、同圓心角的兩扇形。$\\overset{\\frown}{AB}=12\\pi$ cm、$\\overset{\\frown}{CD}=16\\pi$ cm、$OA=30$ cm。</p>\n</blockquote>\n<p>弧長與半徑成正比：</p>\n<p>$$\\frac{OC}{OA} = \\frac{16\\pi}{12\\pi} \\;\\Rightarrow\\; OC = 30\\times\\frac{16}{12} = 40$$</p>\n<p>$$AC = OC-OA = 10\\text{ cm}$$</p>\n<p><strong>答案：B　10 cm</strong></p>",
   "file": "2012_II_解答.md"
