   "section": "Paper 2　Section A",
   "tags": [
    "平行四邊形面積（同高比例）"
   ],
   "text": "> 圖：$ABCD$ 平行四邊形，$E$ 在 $AB$、$F$ 在 $CD$ 上，$AD$ 延線與 $EF$ 延線交於 $G$。$DF:FC=3:4$、$AD:DG=1:1$，$\\triangle DFG$ 面積 $=3$ cm²。\n\n> 關鍵：$\\triangle DFG$ 以 $DF$ 為底，與平行四邊形以 $DC$ 為底，兩者**等高**（同一對平行線之間）。設此高為 $h$。\n\n由 $DF:FC = 3:4$，得 $DF = \\dfrac{3}{7}DC$。\n\n$$[\\triangle DFG] = \\frac12 \\times \\frac{3}{7}DC \\times h = 3 \\;\\Rightarrow\\; DC\\cdot h = 14$$\n\n$$[ABCD] = DC \\times h = 14 \\text{ cm}^2$$\n\n**答案：B　14 cm²**",
   "html": "<blockquote>\n<p>圖：$ABCD$ 平行四邊形，$E$ 在 $AB$、$F$ 在 $CD$ 上，$AD$ 延線與 $EF$ 延線交於 $G$。$DF:FC=3:4$、$AD:DG=1:1$，$\\triangle DFG$ 面積 $=3$ cm²。</p>\n<p>關鍵：$\\triangle DFG$ 以 $DF$ 為底，與平行四邊形以 $DC$ 為底，兩者<strong>等高</strong>（同一對平行線之間）。設此高為 $h$。</p>\n</blockquote>\n<p>由 $DF:FC = 3:4$，得 $DF = \\dfrac{3}{7}DC$。</p>\n<p>$$[\\triangle DFG] = \\frac12 \\times \\frac{3}{7}DC \\times h = 3 \\;\\Rightarrow\\; DC\\cdot h = 14$$</p>\n<p>$$[ABCD] = DC \\times h = 14 \\text{ cm}^2$$</p>\n<p><strong>答案：B　14 cm²</strong></p>",
