   "text": "> 圖：陰影（含邊界）由 $y=x+3$、$y=3$、$y=6-2x$ 圍成的三角形（頂點 $(0,3),(1,4),(1.5,3)$）。$(h,k)$ 在區域內。\n\n三個約束逐條翻譯：\n\n- 在 $y=3$ 之上：$k\\ge3$ ✔（I）\n- 在 $y=x+3$ 之下：$k\\le h+3 \\Leftrightarrow h-k\\ge-3$ ✔（II）\n- 在 $y=6-2x$ 之下：$k\\le 6-2h \\Leftrightarrow 2h+k\\le6$ ✔（III）\n\n**答案：D　I, II and III**",
   "html": "<blockquote>\n<p>圖：陰影（含邊界）由 $y=x+3$、$y=3$、$y=6-2x$ 圍成的三角形（頂點 $(0,3),(1,4),(1.5,3)$）。$(h,k)$ 在區域內。</p>\n</blockquote>\n<p>三個約束逐條翻譯：</p>\n<ul>\n<li>在 $y=3$ 之上：$k\\ge3$ ✔（I）</li>\n<li>在 $y=x+3$ 之下：$k\\le h+3 \\Leftrightarrow h-k\\ge-3$ ✔（II）</li>\n<li>在 $y=6-2x$ 之下：$k\\le 6-2h \\Leftrightarrow 2h+k\\le6$ ✔（III）</li>\n</ul>\n<p><strong>答案：D　I, II and III</strong></p>",
   "file": "2012_II_解答.md"
