   "html": "<p>$a_{18}=26$、$a_{23}=61$。</p>\n<p>公差：</p>\n<p>$$d = \\frac{61-26}{23-18} = 7,\\qquad a_1 = 26-17(7) = -93$$</p>\n<ul>\n<li>I：$a_{14} = a_{18}-4d = 26-28 = -2 &lt; 0$ ✔</li>\n<li>II：$a_1-a_2 = -d = -7 &lt; 0$ ✔</li>\n<li>III：$S_{27} = \\dfrac{27}{2}(a_1+a_{27}) = \\dfrac{27}{2}(-93+89) = -54 &lt; 0$，不是 $&gt;0$ ✘</li>\n</ul>\n<p><strong>答案：A　I and II only</strong></p>",
   "file": "2012_II_解答.md"
