   "html": "<p>$y=f(x-2)+1$：$f(x)$ <strong>右移 2、上移 1</strong>。</p>\n<ul>\n<li>A：標示的 $f(x-2)+1$ 在左邊（左移）✘</li>\n<li>B：右移但下沉 ✘</li>\n<li><strong>C：右邊曲線頂點在右上方，右移 2 上移 1 ✔</strong></li>\n<li>D：左移 ✘</li>\n</ul>\n<p><strong>答案：C</strong></p>",
