   "text": "> 圖：曲線在 $x=0$ 取最大值 $7$，$x=90$ 取最小值 $1$，$x=180$ 回到 $7$。\n\n最大 − 最小 $=6$ → 幅度 $3$；中線 $= (7+1)/2 = 4$。\n\n最大值在 $x=0$ 與 $x=180$ → 週期 $=180^\\circ$ → $\\cos 2x^\\circ$。\n\n$$y = 4+3\\cos 2x^\\circ$$\n\n（驗證：$x=90$：$4+3\\cos 180^\\circ = 1$ ✔）\n\n**答案：D　$y=4+3\\cos 2x^\\circ$**",
   "html": "<blockquote>\n<p>圖：曲線在 $x=0$ 取最大值 $7$，$x=90$ 取最小值 $1$，$x=180$ 回到 $7$。</p>\n</blockquote>\n<p>最大 − 最小 $=6$ → 幅度 $3$；中線 $= (7+1)/2 = 4$。</p>\n<p>最大值在 $x=0$ 與 $x=180$ → 週期 $=180^\\circ$ → $\\cos 2x^\\circ$。</p>\n<p>$$y = 4+3\\cos 2x^\\circ$$</p>\n<p>（驗證：$x=90$：$4+3\\cos 180^\\circ = 1$ ✔）</p>\n<p><strong>答案：D　$y=4+3\\cos 2x^\\circ$</strong></p>",
   "file": "2012_II_解答.md"
