   "text": "12 男 8 女，選 5 人隊伍且**至少一名女生**，求組合數。\n\n用補集法（全部 − 全男）：\n\n$$^{20}C_5 - {}^{12}C_5 = 15504 - 792 = 14712$$\n\n**答案：B　14712**",
   "html": "<p>12 男 8 女，選 5 人隊伍且<strong>至少一名女生</strong>，求組合數。</p>\n<p>用補集法（全部 − 全男）：</p>\n<p>$$^{20}C_5 - {}^{12}C_5 = 15504 - 792 = 14712$$</p>\n<p><strong>答案：B　14712</strong></p>",
   "file": "2012_II_解答.md"
