   "text": "(a) 設 $\\text{f}(x)=36x-x^2$。利用配方法，求 $y=\\text{f}(x)$ 的圖像的頂點的坐標。（2 分）\n\n(b) 一條繩子的長度為 108 m。某保安員將該繩子分割為兩條。一條用作圍成一面積為 $A\\text{ m}^2$ 的長方形禁區；另一條長度為 $x$ m，且用作將這禁區分成兩長方形區域，如圖 2 所示。\n\n![2013 P1 Q17 圖 2](2013P1_figs_svg/2013P1_Q17.svg)\n\n　(i) 以 $x$ 表 $A$。\n\n　(ii) 該保安員宣稱這禁區的面積可大於 $500\\text{ m}^2$。你是否同意？試解釋你的答案。（4 分）",
