   "text": "現對某城市公共房屋的發展進行研究。已知第 1 年年終時所有公屋單位的總樓面面積為 $9\\times10^6\\text{ m}^2$，並且在隨後各年裏，每年所落成的公屋單位的總樓面面積均為前一年年終時全部公屋單位的總樓面面積之 $r\\%$，其中 $r$ 為一常數，而每年所拆除的公屋單位的總樓面面積均為 $3\\times10^5\\text{ m}^2$。現知第 3 年年終時所有公屋單位的總樓面面積為 $1.026\\times10^7\\text{ m}^2$。\n\n(a) (i) 以 $r$ 表第 2 年年終時所有公屋單位的總樓面面積。\n\n　　(ii) 求 $r$。（4 分）\n\n(b) (i) 以 $n$ 表第 $n$ 年年終時所有公屋單位的總樓面面積。\n\n　　(ii) 哪一年年終時所有公屋單位的總樓面面積會首次超過 $4\\times10^7\\text{ m}^2$？（5 分）\n\n(c) 現假設第 $n$ 年年終時所需公屋單位的總樓面面積為 $(a(1.21)^n+b)\\text{ m}^2$，其中 $a$ 及 $b$ 均為常數。某些研究結果顯示下列資料：\n\n| $n$ | 第 $n$ 年年終時所需公屋單位的總樓面面積（m²） |\n|---|---|\n| 1 | $1\\times10^7$ |\n| 2 | $1.063\\times10^7$ |\n\n一研究助理宣稱基於上述假設，某年年終時所有公屋單位的總樓面面積會大於所需公屋單位的總樓面面積。該宣稱是否正確？試解釋你的答案。（4 分）",
   "html": "<p>現對某城市公共房屋的發展進行研究。已知第 1 年年終時所有公屋單位的總樓面面積為 $9\\times10^6\\text{ m}^2$，並且在隨後各年裏，每年所落成的公屋單位的總樓面面積均為前一年年終時全部公屋單位的總樓面面積之 $r\\%$，其中 $r$ 為一常數，而每年所拆除的公屋單位的總樓面面積均為 $3\\times10^5\\text{ m}^2$。現知第 3 年年終時所有公屋單位的總樓面面積為 $1.026\\times10^7\\text{ m}^2$。</p>\n<p>(a) (i) 以 $r$ 表第 2 年年終時所有公屋單位的總樓面面積。</p>\n<p>(ii) 求 $r$。（4 分）</p>\n<p>(b) (i) 以 $n$ 表第 $n$ 年年終時所有公屋單位的總樓面面積。</p>\n<p>(ii) 哪一年年終時所有公屋單位的總樓面面積會首次超過 $4\\times10^7\\text{ m}^2$？（5 分）</p>\n<p>(c) 現假設第 $n$ 年年終時所需公屋單位的總樓面面積為 $(a(1.21)^n+b)\\text{ m}^2$，其中 $a$ 及 $b$ 均為常數。某些研究結果顯示下列資料：</p>\n<table>\n<thead>\n<tr>\n<th>$n$</th>\n<th>第 $n$ 年年終時所需公屋單位的總樓面面積（m²）</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td>$1\\times10^7$</td>\n</tr>\n<tr>\n<td>2</td>\n<td>$1.063\\times10^7$</td>\n</tr>\n</tbody>\n</table>\n<p>一研究助理宣稱基於上述假設，某年年終時所有公屋單位的總樓面面積會大於所需公屋單位的總樓面面積。該宣稱是否正確？試解釋你的答案。（4 分）</p>",
