   "text": "$X$ 城與 $Y$ 城相距 $80\\ \\mathrm{km}$。圖 2 顯示在某上午 7:30 至 9:30 期間，在 $X$ 城與 $Y$ 城之間的同一路上汽車 $A$ 及汽車 $B$ 行駛的圖像。汽車 $A$ 在該期間以恆速率行駛。汽車 $B$ 於該上午 8:15 停下。\n\n![2014 P1 Q10 圖2 距離時間圖](2014P1_figs_svg/2014P1_Q10.svg)\n\n(a)　求於該上午 8:15 汽車 $A$ 與 $X$ 城間之距離。（2 分）\n\n(b)　在該上午 7:30 之後，汽車 $A$ 與汽車 $B$ 於甚麼時間首次相遇？（2 分）\n\n(c)　汽車 $B$ 的司機宣稱在該上午 8:15 至 9:30 期間，汽車 $B$ 的平均速率較汽車 $A$ 高。你是否同意？試解釋你的答案。（2 分）",
