   "text": "759Store, a local retailer of imported snacks, expands its business to sell cosmetics and skincare products. Which of the following is the **LEAST** likely motive behind the expansion?\n\n- A. to reduce competition\n- B. to enjoy economies of scale\n- C. to extend its brand name to other products\n- D. to spread risk by business diversification",
   "html": "<p>759Store, a local retailer of imported snacks, expands its business to sell cosmetics and skincare products. Which of the following is the <strong>LEAST</strong> likely motive behind the expansion?</p>\n<ul>\n<li>A. to reduce competition</li>\n<li>B. to enjoy economies of scale</li>\n<li>C. to extend its brand name to other products</li>\n<li>D. to spread risk by business diversification</li>\n</ul>",
