   "text": "Study the following balance sheet of a banking system. The required reserve ratio is 20%.\n\n| Assets (\\$million) | | Liabilities (\\$million) | |\n|---|---|---|---|\n| Reserves | 300 | Deposits | 1 000 |\n| Loans | 700 | | |\n\nIf the central bank issues newly printed banknotes worth \\$200 million, the cash held by the non-bank public will increase by \\$100 million and the money supply will increase by \\$500 million. The total amount of excess reserves in the banking system will then be \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_.\n\n- A. \\$100 million\n- B. \\$120 million\n- C. \\$280 million\n- D. \\$400 million",
   "html": "<p>Study the following balance sheet of a banking system. The required reserve ratio is 20%.</p>\n<table>\n<thead>\n<tr>\n<th>Assets (\\$million)</th>\n<th></th>\n<th>Liabilities (\\$million)</th>\n<th></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Reserves</td>\n<td>300</td>\n<td>Deposits</td>\n<td>1 000</td>\n</tr>\n<tr>\n<td>Loans</td>\n<td>700</td>\n<td></td>\n<td></td>\n</tr>\n</tbody>\n</table>\n<p>If the central bank issues newly printed banknotes worth \\$200 million, the cash held by the non-bank public will increase by \\$100 million and the money supply will increase by \\$500 million. The total amount of excess reserves in the banking system will then be __________.</p>\n<ul>\n<li>A. \\$100 million</li>\n<li>B. \\$120 million</li>\n<li>C. \\$280 million</li>\n<li>D. \\$400 million</li>\n</ul>",
