   "text": "The following table shows the amounts of consumption on two goods in Country A and Country B before international trade. Assume both countries use one unit of resources on producing Good X and one unit of resources on producing Good Y.\n\n<table>\n<tr><th></th><th colspan=\"3\">Consumption before trade (units)</th></tr>\n<tr><th></th><th>Good X</th><th></th><th>Good Y</th></tr>\n<tr><td>Country A</td><td>100</td><td>and</td><td>25</td></tr>\n<tr><td>Country B</td><td>80</td><td>and</td><td>40</td></tr>\n</table>\n\nIf Country A and Country B completely specialise their production and trade with each other, the total output of both countries will increase by \\_\\_\\_\\_\\_\\_ units of Good X and \\_\\_\\_\\_\\_\\_ units of Good Y.\n\n- A. 15 ...... 15\n- B. 15 ...... 20\n- C. 20 ...... 15\n- D. 20 ...... 20",
   "html": "<p>The following table shows the amounts of consumption on two goods in Country A and Country B before international trade. Assume both countries use one unit of resources on producing Good X and one unit of resources on producing Good Y.</p>\n<table>\n<tr><th></th><th colspan=\"3\">Consumption before trade (units)</th></tr>\n<tr><th></th><th>Good X</th><th></th><th>Good Y</th></tr>\n<tr><td>Country A</td><td>100</td><td>and</td><td>25</td></tr>\n<tr><td>Country B</td><td>80</td><td>and</td><td>40</td></tr>\n</table>\n\n<p>If Country A and Country B completely specialise their production and trade with each other, the total output of both countries will increase by ______ units of Good X and ______ units of Good Y.</p>\n<ul>\n<li>A. 15 ...... 15</li>\n<li>B. 15 ...... 20</li>\n<li>C. 20 ...... 15</li>\n<li>D. 20 ...... 20</li>\n</ul>",
