   "text": "The diagram below shows the market situation of Good X in a small open economy.\n\n![fig_2020P1_q43](2020_P1_images/fig_2020P1_q43.png)\n\n$P_0$ is the price before trade and $P_1$ is the price after trade. Which of the following statements about Good X are correct after the economy opens up for international trade?\n(1) The total expenditure on Good X of domestic consumers would be $P_1\\times Q_d$.\n(2) The value of domestically produced Good X would be $P_1\\times Q_s$.\n(3) The shortage of Good X would be $Q_d-Q_s$.\n\n- A. (1) and (2) only\n- B. (1) and (3) only\n- C. (2) and (3) only\n- D. (1), (2) and (3)",
   "html": "<p>The diagram below shows the market situation of Good X in a small open economy.</p>\n<p><img alt=\"fig_2020P1_q43\" src=\"2020_P1_images/fig_2020P1_q43.png\" /></p>\n<p>$P_0$ is the price before trade and $P_1$ is the price after trade. Which of the following statements about Good X are correct after the economy opens up for international trade?\n(1) The total expenditure on Good X of domestic consumers would be $P_1\\times Q_d$.\n(2) The value of domestically produced Good X would be $P_1\\times Q_s$.\n(3) The shortage of Good X would be $Q_d-Q_s$.</p>\n<ul>\n<li>A. (1) and (2) only</li>\n<li>B. (1) and (3) only</li>\n<li>C. (2) and (3) only</li>\n<li>D. (1), (2) and (3)</li>\n</ul>",
