   "text": "利用分餾塔可以把石油分餾出不同餾分。在分餾塔的較上部分取得餾分 U，在分餾塔的較下部分取得餾分 L。下列的陳述，何者正確？\n\n- A. 與餾分 L 相比，餾分 U 具較高的沸點範圍和較高的黏度\n- B. 與餾分 L 相比，餾分 U 具較高的沸點範圍和較低的黏度\n- C. 與餾分 L 相比，餾分 U 具較低的沸點範圍和較高的黏度\n- D. 與餾分 L 相比，餾分 U 具較低的沸點範圍和較低的黏度",
   "html": "<p>利用分餾塔可以把石油分餾出不同餾分。在分餾塔的較上部分取得餾分 U，在分餾塔的較下部分取得餾分 L。下列的陳述，何者正確？</p>\n<ul>\n<li>A. 與餾分 L 相比，餾分 U 具較高的沸點範圍和較高的黏度</li>\n<li>B. 與餾分 L 相比，餾分 U 具較高的沸點範圍和較低的黏度</li>\n<li>C. 與餾分 L 相比，餾分 U 具較低的沸點範圍和較高的黏度</li>\n<li>D. 與餾分 L 相比，餾分 U 具較低的沸點範圍和較低的黏度</li>\n</ul>",
