   "text": "考慮下列各陳述句並選出最佳的答案：\n\n第一陳述句：丁烷和甲基丙烷具有相同的物理性質\n第二陳述句：丁烷和甲基丙烷具有相同的分子式\n\n- A. 兩陳述句均正確，而第二陳述句為第一陳述句的合理解釋\n- B. 兩陳述句均正確，但第二陳述句並非第一陳述句的合理解釋\n- C. 第一陳述句錯誤，但第二陳述句正確\n- D. 兩陳述句均錯誤",
   "html": "<p>考慮下列各陳述句並選出最佳的答案：</p>\n<p>第一陳述句：丁烷和甲基丙烷具有相同的物理性質\n第二陳述句：丁烷和甲基丙烷具有相同的分子式</p>\n<ul>\n<li>A. 兩陳述句均正確，而第二陳述句為第一陳述句的合理解釋</li>\n<li>B. 兩陳述句均正確，但第二陳述句並非第一陳述句的合理解釋</li>\n<li>C. 第一陳述句錯誤，但第二陳述句正確</li>\n<li>D. 兩陳述句均錯誤</li>\n</ul>",
