   "text": "為探究 H₂O₂(aq) 分解生成 O₂(g)，在室內條件和相同分量的適當催化劑下，以 H₂O₂(aq) 進行了兩次實驗。所用的 H₂O₂(aq) 的濃度和體積如下所示：\n\n| 實驗 | I | II |\n|---|---|---|\n| H₂O₂(aq) 的濃度/M | 1.0 | 0.5 |\n| H₂O₂(aq) 的體積/cm³ | 25 | 50 |\n\n下列哪幅坐標圖正確顯示在以上兩次實驗中釋出 O₂(g) 的體積隨時間的變化？\n\n![Q25 四次實驗的坐標圖選項](2023_P1A_crops/q25.png)\n\n- A.\n- B.\n- C.\n- D.",
