   "html": "<p>考慮以下在室內條件下的平衡體系：</p>\n<p>Fe³⁺(aq) + SCN⁻(aq) ⇌ Fe(SCN)²⁺(aq)</p>\n<p>把小量 Fe(NO₃)₃(s) 加進該平衡混合物，最終在相同條件下達致一個新的平衡。與原本的平衡比較，下列哪個有關這新的平衡的組合正確？</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>A</th>\n<th>B</th>\n<th>C</th>\n<th>D</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>逆向反應的速率</td>\n<td>減少</td>\n<td>減少</td>\n<td>增加</td>\n<td>增加</td>\n</tr>\n<tr>\n<td>Fe(SCN)²⁺(aq) 的濃度</td>\n<td>不變</td>\n<td>增加</td>\n<td>不變</td>\n<td>增加</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>A. 組合 A</li>\n<li>B. 組合 B</li>\n<li>C. 組合 C</li>\n<li>D. 組合 D</li>\n</ul>",
