   "text": "考慮下列各陳述句並選出最佳的答案：\n\n第一陳述句：CH₃CH₂CH₂CH₂COO⁻Na⁺ 是一種肥皂\n第二陳述句：CH₃CH₂CH₂CH₂COO⁻Na⁺ 具有親水性的 −COO⁻ 基團\n\n- A. 兩陳述句均正確，而第二陳述句為第一陳述句的合理解釋\n- B. 兩陳述句均正確，但第二陳述句並非第一陳述句的合理解釋\n- C. 第一陳述句錯誤，但第二陳述句正確\n- D. 兩陳述句均錯誤\n\n---\n\n*甲部完 —*\n\n## 待人工核對\n\n本卷為第 2 層文字交貨，由 easyocr（ch_tra+en，GPU）掃描底稿清洗而成；現模型無影像輸入，未能對頁影像覆核。以下題號建議第 3 層精修時對頁覆核：\n\n- 第 9 題：C₈H₁₈ 裂解的四條方程式（選項 A–D 的裂解產物）OCR 嚴重亂碼，已按原子守恆作最佳重建但仍待對頁核實。\n- 第 13 題：電解硫酸銅(II)組合表的陽極／陰極材料（鉑／銅／石墨）排列 OCR 不完整，部分格以 [?] 標示。\n- 第 29 題：K₁ 與 K₂ 數學關係的四個選項 OCR 無法辨識，僅重建 A（K₁ = 1/K₂），B–D 待對頁核實。\n- 第 3 題：選項 C、D 的「氧化銅(II)／氯化銅(II)」價態標註待對頁核實。\n- 第 5、11、21、25、31、34 題：圖為 300dpi 原卷截圖（程式定位＋墨跡覆蓋率校驗；無視覺覆核，位置／範圍待 spot-check）；第 3 層再換成向量重繪。",
   "html": "<p>考慮下列各陳述句並選出最佳的答案：</p>\n<p>第一陳述句：CH₃CH₂CH₂CH₂COO⁻Na⁺ 是一種肥皂\n第二陳述句：CH₃CH₂CH₂CH₂COO⁻Na⁺ 具有親水性的 −COO⁻ 基團</p>\n<ul>\n<li>A. 兩陳述句均正確，而第二陳述句為第一陳述句的合理解釋</li>\n<li>B. 兩陳述句均正確，但第二陳述句並非第一陳述句的合理解釋</li>\n<li>C. 第一陳述句錯誤，但第二陳述句正確</li>\n<li>D. 兩陳述句均錯誤</li>\n</ul>\n<hr />\n<p><em>甲部完 —</em></p>\n<h2>待人工核對</h2>\n<p>本卷為第 2 層文字交貨，由 easyocr（ch_tra+en，GPU）掃描底稿清洗而成；現模型無影像輸入，未能對頁影像覆核。以下題號建議第 3 層精修時對頁覆核：</p>\n<ul>\n<li>第 9 題：C₈H₁₈ 裂解的四條方程式（選項 A–D 的裂解產物）OCR 嚴重亂碼，已按原子守恆作最佳重建但仍待對頁核實。</li>\n<li>第 13 題：電解硫酸銅(II)組合表的陽極／陰極材料（鉑／銅／石墨）排列 OCR 不完整，部分格以 [?] 標示。</li>\n<li>第 29 題：K₁ 與 K₂ 數學關係的四個選項 OCR 無法辨識，僅重建 A（K₁ = 1/K₂），B–D 待對頁核實。</li>\n<li>第 3 題：選項 C、D 的「氧化銅(II)／氯化銅(II)」價態標註待對頁核實。</li>\n<li>第 5、11、21、25、31、34 題：圖為 300dpi 原卷截圖（程式定位＋墨跡覆蓋率校驗；無視覺覆核，位置／範圍待 spot-check）；第 3 層再換成向量重繪。</li>\n</ul>",
