   "text": "鈣 (Ca) 和鍶 (Sr) 都是周期表中的第 II 族元素。\n\n(a)　第 II 族的名稱是什麼？（1 分）\n\n(b)　石灰水是飽和氫氧化鈣溶液。\n\n　　(i)　把二氧化碳氣體通入石灰水直至溶液變成乳濁。寫出所涉及反應的化學方程式。（1 分）\n\n　　(ii)　當把過量的二氧化碳氣體通入在 (b)(i) 的乳濁液時，生成了一個無色溶液。這反應的生成物是什麼？（1 分）\n\n(c)　下表顯示在一個鍶的樣本中每個同位素的豐度：\n\n| 同位素 | ⁸⁴Sr | ⁸⁶Sr | ⁸⁷Sr | ⁸⁸Sr |\n|---|---|---|---|---|\n| 豐度 (%) | 0.56 | 9.86 | 7.02 | 82.56 |\n\n計算這樣本中鍶的相對原子質量。（2 分）\n\n(d)　鍶與氯反應生成氯化鍶。\n\n　　(i)　繪出氯化鍶的電子圖（只需顯示最外層的電子）。（1 分）\n\n　　(ii)　完成以下各句子：\n\n　　(1)　固體鍶的結構類別是 [?] 結構，而\n　　(2)　固體氯化鍶的結構類別是 [?] 結構。（2 分）\n\n　　(iii)　寫出及解釋固體鍶和固體氯化鍶在導電性方面的差異。（2 分）",
   "html": "<p>鈣 (Ca) 和鍶 (Sr) 都是周期表中的第 II 族元素。</p>\n<p>(a)　第 II 族的名稱是什麼？（1 分）</p>\n<p>(b)　石灰水是飽和氫氧化鈣溶液。</p>\n<p>(i)　把二氧化碳氣體通入石灰水直至溶液變成乳濁。寫出所涉及反應的化學方程式。（1 分）</p>\n<p>(ii)　當把過量的二氧化碳氣體通入在 (b)(i) 的乳濁液時，生成了一個無色溶液。這反應的生成物是什麼？（1 分）</p>\n<p>(c)　下表顯示在一個鍶的樣本中每個同位素的豐度：</p>\n<table>\n<thead>\n<tr>\n<th>同位素</th>\n<th>⁸⁴Sr</th>\n<th>⁸⁶Sr</th>\n<th>⁸⁷Sr</th>\n<th>⁸⁸Sr</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>豐度 (%)</td>\n<td>0.56</td>\n<td>9.86</td>\n<td>7.02</td>\n<td>82.56</td>\n</tr>\n</tbody>\n</table>\n<p>計算這樣本中鍶的相對原子質量。（2 分）</p>\n<p>(d)　鍶與氯反應生成氯化鍶。</p>\n<p>(i)　繪出氯化鍶的電子圖（只需顯示最外層的電子）。（1 分）</p>\n<p>(ii)　完成以下各句子：</p>\n<p>(1)　固體鍶的結構類別是 [?] 結構，而\n　　(2)　固體氯化鍶的結構類別是 [?] 結構。（2 分）</p>\n<p>(iii)　寫出及解釋固體鍶和固體氯化鍶在導電性方面的差異。（2 分）</p>",
