   "text": "從硫化鉛(II) (PbS) 提取鉛金屬涉及兩個階段。\n\n階段 I：利用如下所示的實驗裝置把 PbS(s) 和氧氣一起強熱，在燃燒管內生成氧化鉛(II) 和氣體 X，氣體 X 通入酸化 K₂Cr₂O₇(aq) 中。\n\n![Q2 階段I 實驗裝置](2023_P1B_crops/q02a.png)\n\n(a)　建議一個從空氣中獲取氧的方法。（1 分）\n\n(b)　氣體 X 使酸化 K₂Cr₂O₇(aq) 由橙色變為綠色。\n\n　　(i)　氣體 X 是什麼？（1 分）\n\n　　(ii)　寫出氣體 X 與酸化 K₂Cr₂O₇(aq) 反應的離子方程式。（1 分）\n\n(c)　寫出在燃燒管內所發生反應的化學方程式。（1 分）\n\n(d)　從實驗室安全方面而言，解釋應在何處進行這個實驗。（1 分）\n\n階段 II：把在燃燒管內生成的氧化鉛(II) 分離出來及放在炭磚上，然後把該氧化物強熱如下所示。\n\n![Q2 階段II 實驗裝置](2023_P1B_crops/q02b.png)\n\n(e)　(i)　在階段 II 中的反應生成一個固體產物。描述該固體產物的外觀。（1 分）\n\n　　(ii)　根據氧化數，解釋在階段 II 中的反應是否為氧化還原反應。（1 分）",
   "html": "<p>從硫化鉛(II) (PbS) 提取鉛金屬涉及兩個階段。</p>\n<p>階段 I：利用如下所示的實驗裝置把 PbS(s) 和氧氣一起強熱，在燃燒管內生成氧化鉛(II) 和氣體 X，氣體 X 通入酸化 K₂Cr₂O₇(aq) 中。</p>\n<p><img alt=\"Q2 階段I 實驗裝置\" src=\"chem_2023_P1B_crops/q02a.png\" /></p>\n<p>(a)　建議一個從空氣中獲取氧的方法。（1 分）</p>\n<p>(b)　氣體 X 使酸化 K₂Cr₂O₇(aq) 由橙色變為綠色。</p>\n<p>(i)　氣體 X 是什麼？（1 分）</p>\n<p>(ii)　寫出氣體 X 與酸化 K₂Cr₂O₇(aq) 反應的離子方程式。（1 分）</p>\n<p>(c)　寫出在燃燒管內所發生反應的化學方程式。（1 分）</p>\n<p>(d)　從實驗室安全方面而言，解釋應在何處進行這個實驗。（1 分）</p>\n<p>階段 II：把在燃燒管內生成的氧化鉛(II) 分離出來及放在炭磚上，然後把該氧化物強熱如下所示。</p>\n<p><img alt=\"Q2 階段II 實驗裝置\" src=\"chem_2023_P1B_crops/q02b.png\" /></p>\n<p>(e)　(i)　在階段 II 中的反應生成一個固體產物。描述該固體產物的外觀。（1 分）</p>\n<p>(ii)　根據氧化數，解釋在階段 II 中的反應是否為氧化還原反應。（1 分）</p>",
