   "text": "下表顯示以三種金屬 A、B 和 C 進行了數個實驗的結果。\n\n| 金屬 | A | B | C |\n|---|---|---|---|\n| 與水反應 | 沒有可觀察變化 | 沒有可觀察變化 | 劇烈地反應 |\n| 與稀氫氯酸反應 | 緩緩地釋出無色氣體 I | 沒有可觀察變化 | （這實驗是危險的，不應進行） |\n| 在空氣中強熱 | 冷卻後得到白色固體 | 沒有可觀察變化 | 以淡紫色火焰燃燒 |\n\n(a)　根據以上實驗結果，把這三種金屬按活性的遞減次序排列。（1 分）\n\n(b)　建議一個對氣體 I 的測試。（1 分）\n\n(c)　(i)　寫出金屬 C 與水劇烈地反應時的一項預期觀察。（1 分）\n\n　　(ii)　解釋為什麼進行金屬 C 與稀氫氯酸的反應是危險的。（1 分）\n\n(d)　只利用下列各項，概述實驗步驟並寫出一項預期的觀察：以確定金屬 A 和金屬 B 的相對活性。\n\n[一條金屬 A、一條金屬 B、A(NO₃)₃(aq)[?]、B(NO₃)₃(aq)[?]、數支試管]（2 分）",
   "html": "<p>下表顯示以三種金屬 A、B 和 C 進行了數個實驗的結果。</p>\n<table>\n<thead>\n<tr>\n<th>金屬</th>\n<th>A</th>\n<th>B</th>\n<th>C</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>與水反應</td>\n<td>沒有可觀察變化</td>\n<td>沒有可觀察變化</td>\n<td>劇烈地反應</td>\n</tr>\n<tr>\n<td>與稀氫氯酸反應</td>\n<td>緩緩地釋出無色氣體 I</td>\n<td>沒有可觀察變化</td>\n<td>（這實驗是危險的，不應進行）</td>\n</tr>\n<tr>\n<td>在空氣中強熱</td>\n<td>冷卻後得到白色固體</td>\n<td>沒有可觀察變化</td>\n<td>以淡紫色火焰燃燒</td>\n</tr>\n</tbody>\n</table>\n<p>(a)　根據以上實驗結果，把這三種金屬按活性的遞減次序排列。（1 分）</p>\n<p>(b)　建議一個對氣體 I 的測試。（1 分）</p>\n<p>(c)　(i)　寫出金屬 C 與水劇烈地反應時的一項預期觀察。（1 分）</p>\n<p>(ii)　解釋為什麼進行金屬 C 與稀氫氯酸的反應是危險的。（1 分）</p>\n<p>(d)　只利用下列各項，概述實驗步驟並寫出一項預期的觀察：以確定金屬 A 和金屬 B 的相對活性。</p>\n<p>[一條金屬 A、一條金屬 B、A(NO₃)₃(aq)[?]、B(NO₃)₃(aq)[?]、數支試管]（2 分）</p>",
