   "text": "亞酒石酸 (C₃H₄O₅[?]) 是一種在青瓜中找到的有機酸。\n\n(a)　(i)　24.62 cm³ 的 0.207 M NaOH(aq) 可以完全中和 25.00 cm³ 的 0.102 M 亞酒石酸。計算亞酒石酸的鹽基度。（2 分）\n\n　　(ii)　亞酒石酸分子含有一個羥基。寫出亞酒石酸的結構式。（1 分）\n\n(b)　在某些條件下，0.102 M 亞酒石酸的 pH 是 1.87。通過計算，顯示亞酒石酸在水中不是完全電離。（2 分）",
   "html": "<p>亞酒石酸 (C₃H₄O₅[?]) 是一種在青瓜中找到的有機酸。</p>\n<p>(a)　(i)　24.62 cm³ 的 0.207 M NaOH(aq) 可以完全中和 25.00 cm³ 的 0.102 M 亞酒石酸。計算亞酒石酸的鹽基度。（2 分）</p>\n<p>(ii)　亞酒石酸分子含有一個羥基。寫出亞酒石酸的結構式。（1 分）</p>\n<p>(b)　在某些條件下，0.102 M 亞酒石酸的 pH 是 1.87。通過計算，顯示亞酒石酸在水中不是完全電離。（2 分）</p>",
