   "text": "P、Q 和 R 各自代表以下其中的一個化合物：\n\nCHF₃\nCF₄\nHF\n\n以下流程圖可用來辨識 P、Q 和 R。\n\n![Q5 辨識 P、Q、R 流程圖](2023_P1B_crops/q05.png)\n\n(a)　輔以一圖，描述和解釋在 P 分子間氫鍵的形成。（3 分）\n\n(b)　(i)　Q 是什麼？（1 分）\n\n　　(ii)　從分子層面，解釋為什麼 Q 具極性。（1 分）",
