   "text": "己烷 (C₆H₁₄) 是一種液體燃料。在某些實驗條件下，用以下裝置測定了己烷的燃燒焓變。燃燒 0.120 g 的己烷使 100.0 g 的水的溫度上升 13.4 °C。\n\n![Q6 量熱法實驗裝置](2023_P1B_crops/q06.png)\n\n(a)　在這些實驗條件下，計算己烷的燃燒焓變（以 kJ mol⁻¹ 為單位）。（假設該鋁罐的熱容可被略去，以及水的比熱容為 4.20 J g⁻¹ K⁻¹。）（相對原子質量：H = 1.0，C = 12.0）（2 分）\n\n(b)　(i)　寫出己烷完全燃燒的化學方程式（顯示所有物態符號）。（1 分）\n\n　　(ii)　已知以下的標準生成焓變：\n\nC₆H₁₄(l) = −167.2 kJ mol⁻¹，H₂O(l) = −285.9 kJ mol⁻¹，CO₂(g) = −393.5 kJ mol⁻¹\n\n計算己烷的標準燃燒焓變。（2 分）\n\n(c)　除了失熱，舉出一個原因解釋為什麼 (a) 和 (b)(ii) 所得的答案有所不同。（1 分）",
   "html": "<p>己烷 (C₆H₁₄) 是一種液體燃料。在某些實驗條件下，用以下裝置測定了己烷的燃燒焓變。燃燒 0.120 g 的己烷使 100.0 g 的水的溫度上升 13.4 °C。</p>\n<p><img alt=\"Q6 量熱法實驗裝置\" src=\"chem_2023_P1B_crops/q06.png\" /></p>\n<p>(a)　在這些實驗條件下，計算己烷的燃燒焓變（以 kJ mol⁻¹ 為單位）。（假設該鋁罐的熱容可被略去，以及水的比熱容為 4.20 J g⁻¹ K⁻¹。）（相對原子質量：H = 1.0，C = 12.0）（2 分）</p>\n<p>(b)　(i)　寫出己烷完全燃燒的化學方程式（顯示所有物態符號）。（1 分）</p>\n<p>(ii)　已知以下的標準生成焓變：</p>\n<p>C₆H₁₄(l) = −167.2 kJ mol⁻¹，H₂O(l) = −285.9 kJ mol⁻¹，CO₂(g) = −393.5 kJ mol⁻¹</p>\n<p>計算己烷的標準燃燒焓變。（2 分）</p>\n<p>(c)　除了失熱，舉出一個原因解釋為什麼 (a) 和 (b)(ii) 所得的答案有所不同。（1 分）</p>",
