   "text": "X 和 Y 是碳氫化合物。它們的結構式如下所示：\n\n![Q7 X 和 Y 的結構式](2023_P1B_crops/q07.png)\n\n(a)　寫出 X 的系統名稱。（1 分）\n\n(b)　舉出 X 和 Y 的燃燒特徵的一項不同之處。（1 分）\n\n(c)　除燃燒外，建議一個化學測試來分辨 X 和 Y。（2 分）\n\n(d)　Y 可生成一種聚合物。繪出這聚合物的重複單位。（1 分）",
   "html": "<p>X 和 Y 是碳氫化合物。它們的結構式如下所示：</p>\n<p><img alt=\"Q7 X 和 Y 的結構式\" src=\"chem_2023_P1B_crops/q07.png\" /></p>\n<p>(a)　寫出 X 的系統名稱。（1 分）</p>\n<p>(b)　舉出 X 和 Y 的燃燒特徵的一項不同之處。（1 分）</p>\n<p>(c)　除燃燒外，建議一個化學測試來分辨 X 和 Y。（2 分）</p>\n<p>(d)　Y 可生成一種聚合物。繪出這聚合物的重複單位。（1 分）</p>",
