   "text": "只利用下列各項，設計一個把鎳(II) 電鍍在鐵棒上的實驗。\n\n[直流電源、一條鎳條、一根鐵棒、硫酸鎳(II) 溶液、數條連接線、一個燒杯]\n\n(a)　繪畫一個標示圖以顯示該實驗裝置。（2 分）\n\n(b)　寫出硫酸鎳(II) 溶液在這實驗中的一項功用。（1 分）\n\n(c)　寫出在鐵棒上生成鎳的半反應式。（1 分）\n\n(d)　與 OH⁻(aq) 離子和 SO₄²⁻(aq) 離子相比，Ni(s) 是較強的還原劑。硫酸鎳(II) 溶液是綠色的。預期在這實驗中該溶液有沒有可觀察的變化？解釋你的答案。（2 分）\n\n(e)　寫出把鎳電鍍在鐵器上的一個目的。（1 分）",
   "html": "<p>只利用下列各項，設計一個把鎳(II) 電鍍在鐵棒上的實驗。</p>\n<p>[直流電源、一條鎳條、一根鐵棒、硫酸鎳(II) 溶液、數條連接線、一個燒杯]</p>\n<p>(a)　繪畫一個標示圖以顯示該實驗裝置。（2 分）</p>\n<p>(b)　寫出硫酸鎳(II) 溶液在這實驗中的一項功用。（1 分）</p>\n<p>(c)　寫出在鐵棒上生成鎳的半反應式。（1 分）</p>\n<p>(d)　與 OH⁻(aq) 離子和 SO₄²⁻(aq) 離子相比，Ni(s) 是較強的還原劑。硫酸鎳(II) 溶液是綠色的。預期在這實驗中該溶液有沒有可觀察的變化？解釋你的答案。（2 分）</p>\n<p>(e)　寫出把鎳電鍍在鐵器上的一個目的。（1 分）</p>",
