   "text": "概述利用固體碳酸鎂和稀硫酸來製備硫酸鎂晶體的各步驟。你不需提及所涉及的儀器。（5 分）",
   "html": "<p>概述利用固體碳酸鎂和稀硫酸來製備硫酸鎂晶體的各步驟。你不需提及所涉及的儀器。（5 分）</p>",
