   "text": "化合物 X 和 Y 是順-反異構體。它們具有相同分子式 C₄H₈。\n\n(a)　(i)　X 是極性的，Y 卻是非極性的。寫出 X 的系統名稱。（1 分）\n\n　　(ii)　寫出 Y 的結構式。（1 分）\n\n(b)　一個具旋光性的醇 Z 經脫水後，可生成 X 和 Y 的混合物。\n\n　　(i)　舉出這反應需要的一個試劑及一個反應條件。（1 分）\n\n　　(ii)　寫出 Z 的結構式。（1 分）\n\n　　(iii)　繪出 Z 的一雙對映異構體的三維結構圖。（2 分）\n\n　　(iv)　描述 Z 的一雙對映異構體的旋光性的不同之處。（1 分）",
   "html": "<p>化合物 X 和 Y 是順-反異構體。它們具有相同分子式 C₄H₈。</p>\n<p>(a)　(i)　X 是極性的，Y 卻是非極性的。寫出 X 的系統名稱。（1 分）</p>\n<p>(ii)　寫出 Y 的結構式。（1 分）</p>\n<p>(b)　一個具旋光性的醇 Z 經脫水後，可生成 X 和 Y 的混合物。</p>\n<p>(i)　舉出這反應需要的一個試劑及一個反應條件。（1 分）</p>\n<p>(ii)　寫出 Z 的結構式。（1 分）</p>\n<p>(iii)　繪出 Z 的一雙對映異構體的三維結構圖。（2 分）</p>\n<p>(iv)　描述 Z 的一雙對映異構體的旋光性的不同之處。（1 分）</p>",
   "file": "2023_P1B_QU(CHI).md"
