   "text": "(a)　根據鍵合和結構，解釋以下各氧化物熔點的差異。\n\n| 氧化物 | SiO₂ | P₄O₁₀ | SO₂ |\n|---|---|---|---|\n| 熔點(°C) | 1710 | 340 | −72 |\n\n（3 分）\n\n(b)　(i)　Fe²⁺(aq) 和 H₂O₂(aq) 在酸性介質中反應生成 Fe³⁺(aq) 和 H₂O(l)。寫出這反應的化學方程式。（1 分）\n\n　　(ii)　寫出這反應可怎樣表明鐵展示兩個過渡性金屬的特性。（2 分）",
   "html": "<p>(a)　根據鍵合和結構，解釋以下各氧化物熔點的差異。</p>\n<table>\n<thead>\n<tr>\n<th>氧化物</th>\n<th>SiO₂</th>\n<th>P₄O₁₀</th>\n<th>SO₂</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>熔點(°C)</td>\n<td>1710</td>\n<td>340</td>\n<td>−72</td>\n</tr>\n</tbody>\n</table>\n<p>（3 分）</p>\n<p>(b)　(i)　Fe²⁺(aq) 和 H₂O₂(aq) 在酸性介質中反應生成 Fe³⁺(aq) 和 H₂O(l)。寫出這反應的化學方程式。（1 分）</p>\n<p>(ii)　寫出這反應可怎樣表明鐵展示兩個過渡性金屬的特性。（2 分）</p>",
