   "text": "考慮以下反應：\n\nBr₂(aq) + HCOOH(aq) → 2HBr(aq) + CO₂(g)\n\n描述並解釋如何透過量度反應混合物的顏色深度，來跟隨以上反應的進度。不需描述實驗細節。草繪一幅附有標示的坐標圖以表示預期的結果，並解釋該坐標圖的形狀。（6 分）\n\n---\n\n*乙部完 —*\n\n## 待人工核對\n\n本卷為第 2 層文字交貨，由 easyocr（ch_tra+en，GPU）掃描底稿清洗而成；現模型無影像輸入，未能對頁影像覆核。以下題號建議第 3 層精修時對頁覆核：\n\n- 第 1(d)(ii) 題：完成句子的第一句（固體鍶的結構類別）OCR 無法辨識，以 [?] 標示。\n- 第 3(d) 題：所提供試劑的硝酸鹽化學式（A(NO₃)₃／B(NO₃)₃ 或 A(NO₃)₂／B(NO₃)₂）OCR 不清晰，以 [?] 標示。\n- 第 4 題：亞酒石酸的分子式 OCR 為「CHAOs」，按內容（二元酸、含一個羥基）重建為 C₃H₄O₅，仍待對頁核實。\n- 第 2、5、6、7、10 題：圖為 300dpi 原卷截圖（程式定位＋墨跡覆蓋率校驗；無視覺覆核，位置／範圍待 spot-check）；第 3 層再換成向量重繪。\n- 第 7 題：X、Y 的結構式僅能以截圖保留，X 的系統名稱無法由 OCR 確定，待對頁核實。",
   "html": "<p>考慮以下反應：</p>\n<p>Br₂(aq) + HCOOH(aq) → 2HBr(aq) + CO₂(g)</p>\n<p>描述並解釋如何透過量度反應混合物的顏色深度，來跟隨以上反應的進度。不需描述實驗細節。草繪一幅附有標示的坐標圖以表示預期的結果，並解釋該坐標圖的形狀。（6 分）</p>\n<hr />\n<p><em>乙部完 —</em></p>\n<h2>待人工核對</h2>\n<p>本卷為第 2 層文字交貨，由 easyocr（ch_tra+en，GPU）掃描底稿清洗而成；現模型無影像輸入，未能對頁影像覆核。以下題號建議第 3 層精修時對頁覆核：</p>\n<ul>\n<li>第 1(d)(ii) 題：完成句子的第一句（固體鍶的結構類別）OCR 無法辨識，以 [?] 標示。</li>\n<li>第 3(d) 題：所提供試劑的硝酸鹽化學式（A(NO₃)₃／B(NO₃)₃ 或 A(NO₃)₂／B(NO₃)₂）OCR 不清晰，以 [?] 標示。</li>\n<li>第 4 題：亞酒石酸的分子式 OCR 為「CHAOs」，按內容（二元酸、含一個羥基）重建為 C₃H₄O₅，仍待對頁核實。</li>\n<li>第 2、5、6、7、10 題：圖為 300dpi 原卷截圖（程式定位＋墨跡覆蓋率校驗；無視覺覆核，位置／範圍待 spot-check）；第 3 層再換成向量重繪。</li>\n<li>第 7 題：X、Y 的結構式僅能以截圖保留，X 的系統名稱無法由 OCR 確定，待對頁核實。</li>\n</ul>",
