   "text": "回答試題的所有部分。\n\n(a)　(i)　在工業上，藉以下步驟可用山梨醇來合成丙種維生素：\n\n![Q1(a) 山梨醇合成丙種維生素流程](2023_P2_crops/q1a.png)\n\n　　(1)　解釋為什麼需要在工業上合成丙種維生素。（1 分）\n\n　　(2)　根據綠色化學的原理，解釋為什麼這個合成丙種維生素的過程不被視為「綠色」。（1 分）\n\n　(ii)　甲烷可用來生成合成氣。\n\n　　(1)　提出甲烷的一個來源。（1 分）\n\n　　(2)　寫出從甲烷生成合成氣的化學方程式。（1 分）\n\n　(iii)　寫出由氯鹼工業製造的兩個化學品。（1 分）\n\n(b)　哈柏法是一個生產氨的重要工業過程。所涉及反應的化學方程式如下所示：\n\nN₂(g) + 3H₂(g) ⇌ 2NH₃(g)　ΔH = −92 kJ mol⁻¹\n\n在最佳的操作條件及有鐵催化劑的存在下，在平衡時 NH₃(g) 的產率約為 20%。哈柏法正向反應的活化能是 20 kJ mol⁻¹。\n\n　(i)　「活化能」一詞是什麼意思？（1 分）\n\n　(ii)　繪出哈柏法反應的能線圖，標示各坐標軸及該正向反應的活化能 (Ea)。（2 分）\n\n　(iii)　在相同的操作條件下，找出哈柏法逆向反應的活化能（以 kJ mol⁻¹ 為單位）。（1 分）\n\n　(iv)　寫出在哈柏法中使用的最佳操作溫度與壓強。解釋為何使用這樣的條件。（3 分）\n\n　(v)　評論以下陳述：\n\n「在哈柏法中使用更多鐵催化劑，可以增加氨的產率。」（1 分）\n\n(c)　(i)　工業合成過氧化氫 H₂O₂ 的原料是氫氣和氧氣，合成過程涉及以下兩個步驟：\n\n在步驟(1)中的反應：H₂ + Y → H₂Y\n\nY 是一個有機化合物。把氫氣通入溶於有機溶劑的 Y，使用金屬鈀 (Pd) 作為催化劑。在步驟(1)結束時，移除鈀催化劑。\n\n在步驟(2)中的反應：H₂Y + O₂ → H₂O₂ + Y\n\n把空氣吹入溶於有機溶劑的 H₂Y。在步驟(2)結束時，收集得 H₂O₂ 並且把 Y 回收。\n\n　　(1)　建議一個方法以提升鈀催化劑的效能。（1 分）\n\n　　(2)　解釋為什麼在步驟(2)結束時要把 Y 回收。（1 分）\n\n　　(3)　除了爆炸的潛在危險，解釋為何不把氫氣和氧氣經單一步驟合成為過氧化氫。（1 分）\n\n　(ii)　在相同的實驗條件下，進行了三次實驗來測定以下反應的速率方程：\n\nH₂O₂(aq) + 2I⁻(aq) + 2H⁺(aq) → I₂(aq) + 2H₂O(l)\n\n所得的數據表列如下：\n\n| | 第 1 次 | 第 2 次 | 第 3 次 |\n|---|---|---|---|\n| H₂O₂(aq) 的初始濃度/mol dm⁻³ | 0.0010 | 0.0020 | 0.0010 [?] |\n| I⁻(aq) 的初始濃度/mol dm⁻³ | 0.10 | 0.10 | 0.50 |\n| H⁺(aq) 的初始濃度/mol dm⁻³ | 0.10 | 0.10 | 0.10 |\n| 生成 I₂(aq) 的初速/mol dm⁻³ s⁻¹ | 2.8 × 10⁻⁶ | 5.6 × 10⁻⁶ | 2.8 × 10⁻⁵ |\n\n　　(1)　已知對應 H₂O₂(aq) 的反應級數是 1，推定對應 I⁻(aq) 及對應 H⁺(aq) 的反應級數。（2 分）\n\n　　(2)　根據第 1 次實驗的數據，計算在相同實驗條件下這反應的速率常數。（2 分）\n\n*甲部完 —*",
   "html": "<p>回答試題的所有部分。</p>\n<p>(a)　(i)　在工業上，藉以下步驟可用山梨醇來合成丙種維生素：</p>\n<p><img alt=\"Q1(a) 山梨醇合成丙種維生素流程\" src=\"chem_2023_P2_crops/q1a.png\" /></p>\n<p>(1)　解釋為什麼需要在工業上合成丙種維生素。（1 分）</p>\n<p>(2)　根據綠色化學的原理，解釋為什麼這個合成丙種維生素的過程不被視為「綠色」。（1 分）</p>\n<p>(ii)　甲烷可用來生成合成氣。</p>\n<p>(1)　提出甲烷的一個來源。（1 分）</p>\n<p>(2)　寫出從甲烷生成合成氣的化學方程式。（1 分）</p>\n<p>(iii)　寫出由氯鹼工業製造的兩個化學品。（1 分）</p>\n<p>(b)　哈柏法是一個生產氨的重要工業過程。所涉及反應的化學方程式如下所示：</p>\n<p>N₂(g) + 3H₂(g) ⇌ 2NH₃(g)　ΔH = −92 kJ mol⁻¹</p>\n<p>在最佳的操作條件及有鐵催化劑的存在下，在平衡時 NH₃(g) 的產率約為 20%。哈柏法正向反應的活化能是 20 kJ mol⁻¹。</p>\n<p>(i)　「活化能」一詞是什麼意思？（1 分）</p>\n<p>(ii)　繪出哈柏法反應的能線圖，標示各坐標軸及該正向反應的活化能 (Ea)。（2 分）</p>\n<p>(iii)　在相同的操作條件下，找出哈柏法逆向反應的活化能（以 kJ mol⁻¹ 為單位）。（1 分）</p>\n<p>(iv)　寫出在哈柏法中使用的最佳操作溫度與壓強。解釋為何使用這樣的條件。（3 分）</p>\n<p>(v)　評論以下陳述：</p>\n<p>「在哈柏法中使用更多鐵催化劑，可以增加氨的產率。」（1 分）</p>\n<p>(c)　(i)　工業合成過氧化氫 H₂O₂ 的原料是氫氣和氧氣，合成過程涉及以下兩個步驟：</p>\n<p>在步驟(1)中的反應：H₂ + Y → H₂Y</p>\n<p>Y 是一個有機化合物。把氫氣通入溶於有機溶劑的 Y，使用金屬鈀 (Pd) 作為催化劑。在步驟(1)結束時，移除鈀催化劑。</p>\n<p>在步驟(2)中的反應：H₂Y + O₂ → H₂O₂ + Y</p>\n<p>把空氣吹入溶於有機溶劑的 H₂Y。在步驟(2)結束時，收集得 H₂O₂ 並且把 Y 回收。</p>\n<p>(1)　建議一個方法以提升鈀催化劑的效能。（1 分）</p>\n<p>(2)　解釋為什麼在步驟(2)結束時要把 Y 回收。（1 分）</p>\n<p>(3)　除了爆炸的潛在危險，解釋為何不把氫氣和氧氣經單一步驟合成為過氧化氫。（1 分）</p>\n<p>(ii)　在相同的實驗條件下，進行了三次實驗來測定以下反應的速率方程：</p>\n<p>H₂O₂(aq) + 2I⁻(aq) + 2H⁺(aq) → I₂(aq) + 2H₂O(l)</p>\n<p>所得的數據表列如下：</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>第 1 次</th>\n<th>第 2 次</th>\n<th>第 3 次</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>H₂O₂(aq) 的初始濃度/mol dm⁻³</td>\n<td>0.0010</td>\n<td>0.0020</td>\n<td>0.0010 [?]</td>\n</tr>\n<tr>\n<td>I⁻(aq) 的初始濃度/mol dm⁻³</td>\n<td>0.10</td>\n<td>0.10</td>\n<td>0.50</td>\n</tr>\n<tr>\n<td>H⁺(aq) 的初始濃度/mol dm⁻³</td>\n<td>0.10</td>\n<td>0.10</td>\n<td>0.10</td>\n</tr>\n<tr>\n<td>生成 I₂(aq) 的初速/mol dm⁻³ s⁻¹</td>\n<td>2.8 × 10⁻⁶</td>\n<td>5.6 × 10⁻⁶</td>\n<td>2.8 × 10⁻⁵</td>\n</tr>\n</tbody>\n</table>\n<p>(1)　已知對應 H₂O₂(aq) 的反應級數是 1，推定對應 I⁻(aq) 及對應 H⁺(aq) 的反應級數。（2 分）</p>\n<p>(2)　根據第 1 次實驗的數據，計算在相同實驗條件下這反應的速率常數。（2 分）</p>\n<p><em>甲部完 —</em></p>",
