   "text": "回答試題的所有部分。\n\n(a)　(i)　己二酸 (HOOC(CH₂)₄COOH) 是製造尼龍-6,6 的其中一個單體。以下兩種方法都可以製備己二酸：\n\n方法 I：\n\n濃 HNO₃\n[?] + O₂ → HOOC(CH₂)₄COOH [?]\n\n方法 II：\n\nH₂O₂，催化劑\n[?] + H₂O₂ → HOOC(CH₂)₄COOH + H₂O [?]\n\n根據綠色化學的原理，提出兩個原因為什麼方法 II 比方法 I 被視為較「綠色」。（2 分）\n\n　(ii)　寫出以下分子的兩個結構特徵使其物質呈液晶特性。\n\n![Q2(a)(ii) 液晶分子結構](2023_P2_crops/q2a.png)\n\n（2 分）\n\n　(iii)　脲甲醛是製造電插座常用的聚合物。繪出脲甲醛的重複單位。（1 分）\n\n(b)　下圖顯示銀晶體的晶胞：\n\n![Q2(b)(i) 銀晶體晶胞](2023_P2_crops/q2b.png)\n\n　(i)　寫出這類晶體結構的名稱。（1 分）\n\n　(ii)　推定在以上晶胞的銀原子數目。（2 分）\n\n　(iii)　紋銀[?] 是一種合金。某紋銀樣本由 92.5% 銀和 7.5% 銅組成。\n\n　　(1)　根據鍵合和結構，解釋為何紋銀的熔點比純銀的較低。（2 分）\n\n　　(2)　除價錢外，舉出使用紋銀較使用純銀來製作首飾的一項優點。（1 分）\n\n　(iv)　一個球形簇是由眾多銀原子組成的。這個球形簇的直徑是銀原子直徑的 80 倍。這個球形簇是一顆納米粒子嗎？解釋你的答案。（已知：銀原子直徑 = 0.288 nm）（2 分）\n\n(c)　「冰巾[?]」是由一種屬於縮合聚合物的聚對苯二甲酸乙二酯 (PET) 製造出來的。與大小相同的濕棉巾比較，水分較容易從濕「冰巾[?]」蒸發出來。\n\n　(i)　「縮合聚合物」一詞是什麼意思？（1 分）\n\n　(ii)　PET 可由以下兩個單體製成：\n\nHOCH₂CH₂OH　和　HOOC−C₆H₄−COOH[?]（對苯二甲酸）\n\n寫出生成 PET 的化學方程式。（1 分）\n\n　(iii)　根據分子結構，解釋 PET 是一種熱塑性塑膠還是熱固性塑膠。（1 分）\n\n　(iv)　棉的主要成分是纖維素。根據鍵合和結構，解釋為什麼與大小相同的濕棉巾比較，水分較容易從濕「冰巾[?]」蒸發出來。（2 分）\n\n　(v)　「冰巾[?]」是由 PET 纖維編織而成。提出製造 PET 纖維的一個成型方法。（1 分）\n\n　(vi)　舉出再循環「冰巾[?]」所碰到的一個困難。（1 分）\n\n*乙部完 —*",
   "html": "<p>回答試題的所有部分。</p>\n<p>(a)　(i)　己二酸 (HOOC(CH₂)₄COOH) 是製造尼龍-6,6 的其中一個單體。以下兩種方法都可以製備己二酸：</p>\n<p>方法 I：</p>\n<p>濃 HNO₃\n[?] + O₂ → HOOC(CH₂)₄COOH [?]</p>\n<p>方法 II：</p>\n<p>H₂O₂，催化劑\n[?] + H₂O₂ → HOOC(CH₂)₄COOH + H₂O [?]</p>\n<p>根據綠色化學的原理，提出兩個原因為什麼方法 II 比方法 I 被視為較「綠色」。（2 分）</p>\n<p>(ii)　寫出以下分子的兩個結構特徵使其物質呈液晶特性。</p>\n<p><img alt=\"Q2(a)(ii) 液晶分子結構\" src=\"chem_2023_P2_crops/q2a.png\" /></p>\n<p>（2 分）</p>\n<p>(iii)　脲甲醛是製造電插座常用的聚合物。繪出脲甲醛的重複單位。（1 分）</p>\n<p>(b)　下圖顯示銀晶體的晶胞：</p>\n<p><img alt=\"Q2(b)(i) 銀晶體晶胞\" src=\"chem_2023_P2_crops/q2b.png\" /></p>\n<p>(i)　寫出這類晶體結構的名稱。（1 分）</p>\n<p>(ii)　推定在以上晶胞的銀原子數目。（2 分）</p>\n<p>(iii)　紋銀[?] 是一種合金。某紋銀樣本由 92.5% 銀和 7.5% 銅組成。</p>\n<p>(1)　根據鍵合和結構，解釋為何紋銀的熔點比純銀的較低。（2 分）</p>\n<p>(2)　除價錢外，舉出使用紋銀較使用純銀來製作首飾的一項優點。（1 分）</p>\n<p>(iv)　一個球形簇是由眾多銀原子組成的。這個球形簇的直徑是銀原子直徑的 80 倍。這個球形簇是一顆納米粒子嗎？解釋你的答案。（已知：銀原子直徑 = 0.288 nm）（2 分）</p>\n<p>(c)　「冰巾[?]」是由一種屬於縮合聚合物的聚對苯二甲酸乙二酯 (PET) 製造出來的。與大小相同的濕棉巾比較，水分較容易從濕「冰巾[?]」蒸發出來。</p>\n<p>(i)　「縮合聚合物」一詞是什麼意思？（1 分）</p>\n<p>(ii)　PET 可由以下兩個單體製成：</p>\n<p>HOCH₂CH₂OH　和　HOOC−C₆H₄−COOH[?]（對苯二甲酸）</p>\n<p>寫出生成 PET 的化學方程式。（1 分）</p>\n<p>(iii)　根據分子結構，解釋 PET 是一種熱塑性塑膠還是熱固性塑膠。（1 分）</p>\n<p>(iv)　棉的主要成分是纖維素。根據鍵合和結構，解釋為什麼與大小相同的濕棉巾比較，水分較容易從濕「冰巾[?]」蒸發出來。（2 分）</p>\n<p>(v)　「冰巾[?]」是由 PET 纖維編織而成。提出製造 PET 纖維的一個成型方法。（1 分）</p>\n<p>(vi)　舉出再循環「冰巾[?]」所碰到的一個困難。（1 分）</p>\n<p><em>乙部完 —</em></p>",
