   "text": "參照以下在某些條件下的反應及所給資料：\n\n2FeO(s) + ½O₂(g) → Fe₂O₃(s)\n\nFeO(s) 的生成焓變 = −270 kJ mol⁻¹\nFe₂O₃(s) 的生成焓變 = −820 kJ mol⁻¹\n\n在這些條件下，以下哪個表示式得出以上反應的焓變？\n\n- A. [(−820) − (−270)] kJ mol⁻¹\n- B. [−270 − (−820)] kJ mol⁻¹\n- C. [−820 − (−270 × 2)] kJ mol⁻¹\n- D. [(−270 × 2) − (−820)] kJ mol⁻¹",
   "html": "<p>參照以下在某些條件下的反應及所給資料：</p>\n<p>2FeO(s) + ½O₂(g) → Fe₂O₃(s)</p>\n<p>FeO(s) 的生成焓變 = −270 kJ mol⁻¹\nFe₂O₃(s) 的生成焓變 = −820 kJ mol⁻¹</p>\n<p>在這些條件下，以下哪個表示式得出以上反應的焓變？</p>\n<ul>\n<li>A. [(−820) − (−270)] kJ mol⁻¹</li>\n<li>B. [−270 − (−820)] kJ mol⁻¹</li>\n<li>C. [−820 − (−270 × 2)] kJ mol⁻¹</li>\n<li>D. [(−270 × 2) − (−820)] kJ mol⁻¹</li>\n</ul>",
