   "text": "元素 X 是周期表內首二十個元素之一。X 可生成 XCl₃ 和 XCl₅ 兩種氯化物。XCl₃ 的電子圖（只顯示了最外層的電子）如下所示：\n\n![Q22 XCl₃ 電子圖](2024_P1A_crops/q22.png)\n\n下列哪些有關 X 的陳述正確？\n\n(1) X 屬於周期表的第 V 族。\n(2) X 是在周期表的第三周期。\n(3) 在 XCl₅ 的 X 原子具八隅體電子排佈。\n\n- A. 只有 (1) 和 (2)\n- B. 只有 (1) 和 (3)\n- C. 只有 (2) 和 (3)\n- D. (1)、(2) 和 (3)",
   "html": "<p>元素 X 是周期表內首二十個元素之一。X 可生成 XCl₃ 和 XCl₅ 兩種氯化物。XCl₃ 的電子圖（只顯示了最外層的電子）如下所示：</p>\n<p><img alt=\"Q22 XCl₃ 電子圖\" src=\"chem_2024_P1A_crops/q22.png\" /></p>\n<p>下列哪些有關 X 的陳述正確？</p>\n<p>(1) X 屬於周期表的第 V 族。\n(2) X 是在周期表的第三周期。\n(3) 在 XCl₅ 的 X 原子具八隅體電子排佈。</p>\n<ul>\n<li>A. 只有 (1) 和 (2)</li>\n<li>B. 只有 (1) 和 (3)</li>\n<li>C. 只有 (2) 和 (3)</li>\n<li>D. (1)、(2) 和 (3)</li>\n</ul>",
