   "text": "參考以下熱化學方程式：\n\n2Na(s) + O₂(g) → Na₂O₂(s)　ΔH° = −515 kJ mol⁻¹\n\n下列哪些陳述正確？\n\n(1) Na₂O₂(s) 的標準生成焓變是 −515 kJ mol⁻¹。\n(2) Na(s) 的標準燃燒焓變是 −515 kJ mol⁻¹。\n(3) 在標準條件下，當 2 mol 的 Na(s) 與 1 mol 的 O₂(g) 反應生成 1 mol 的 Na₂O₂(s)，釋出 515 kJ 的熱。\n\n- A. 只有 (1) 和 (2)\n- B. 只有 (1) 和 (3)\n- C. 只有 (2) 和 (3)\n- D. (1)、(2) 和 (3)",
   "html": "<p>參考以下熱化學方程式：</p>\n<p>2Na(s) + O₂(g) → Na₂O₂(s)　ΔH° = −515 kJ mol⁻¹</p>\n<p>下列哪些陳述正確？</p>\n<p>(1) Na₂O₂(s) 的標準生成焓變是 −515 kJ mol⁻¹。\n(2) Na(s) 的標準燃燒焓變是 −515 kJ mol⁻¹。\n(3) 在標準條件下，當 2 mol 的 Na(s) 與 1 mol 的 O₂(g) 反應生成 1 mol 的 Na₂O₂(s)，釋出 515 kJ 的熱。</p>\n<ul>\n<li>A. 只有 (1) 和 (2)</li>\n<li>B. 只有 (1) 和 (3)</li>\n<li>C. 只有 (2) 和 (3)</li>\n<li>D. (1)、(2) 和 (3)</li>\n</ul>",
   "file": "2024_P1A_QU(CHI).md"
