   "text": "考慮下列各陳述句並選出最佳的答案：\n\n第一陳述句：銅與稀硝酸可發生反應，與稀乙酸卻不可。\n第二陳述句：硝酸是強酸，而乙酸是弱酸。\n\n- A. 兩陳述句均正確，而第二陳述句是第一陳述句的合理解釋\n- B. 兩陳述句均正確，而第二陳述句並非第一陳述句的合理解釋\n- C. 第一陳述句錯誤，但第二陳述句正確\n- D. 兩陳述句均錯誤",
