   "text": "為研習以下反應的速率，進行了一個實驗：\n\nX₂(g) → 2X(g)\n\n於某溫度下，在一個固定體積的密閉容器中，X₂(g) 的濃度在首 4 分鐘從 0.10 mol dm⁻³ 減少至 0.04 mol dm⁻³。在首 4 分鐘，X(g) 的平均生成速率是多少？\n\n- A. 0.010 mol dm⁻³ min⁻¹\n- B. 0.015 mol dm⁻³ min⁻¹\n- C. 0.020 mol dm⁻³ min⁻¹\n- D. 0.030 mol dm⁻³ min⁻¹",
   "html": "<p>為研習以下反應的速率，進行了一個實驗：</p>\n<p>X₂(g) → 2X(g)</p>\n<p>於某溫度下，在一個固定體積的密閉容器中，X₂(g) 的濃度在首 4 分鐘從 0.10 mol dm⁻³ 減少至 0.04 mol dm⁻³。在首 4 分鐘，X(g) 的平均生成速率是多少？</p>\n<ul>\n<li>A. 0.010 mol dm⁻³ min⁻¹</li>\n<li>B. 0.015 mol dm⁻³ min⁻¹</li>\n<li>C. 0.020 mol dm⁻³ min⁻¹</li>\n<li>D. 0.030 mol dm⁻³ min⁻¹</li>\n</ul>",
