   "text": "考慮以下反應的速率和粒子間的碰撞情況：\n\n2SO₂(g) + O₂(g) ⇌ 2SO₃(g)\n\n在固定溫度下增加 SO₂(g) 的濃度，下列哪個組合正確？\n\n| | A | B | C | D |\n|---|---|---|---|---|\n| 反應速率 | 增加 | 增加 | 不變 | 不變 |\n| 粒子間的碰撞 | 平均有較多的能量 | 有較高的頻率 | 平均有較多的能量 | 有較高的頻率 |\n\n- A. 組合 A\n- B. 組合 B\n- C. 組合 C\n- D. 組合 D",
   "html": "<p>考慮以下反應的速率和粒子間的碰撞情況：</p>\n<p>2SO₂(g) + O₂(g) ⇌ 2SO₃(g)</p>\n<p>在固定溫度下增加 SO₂(g) 的濃度，下列哪個組合正確？</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>A</th>\n<th>B</th>\n<th>C</th>\n<th>D</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>反應速率</td>\n<td>增加</td>\n<td>增加</td>\n<td>不變</td>\n<td>不變</td>\n</tr>\n<tr>\n<td>粒子間的碰撞</td>\n<td>平均有較多的能量</td>\n<td>有較高的頻率</td>\n<td>平均有較多的能量</td>\n<td>有較高的頻率</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>A. 組合 A</li>\n<li>B. 組合 B</li>\n<li>C. 組合 C</li>\n<li>D. 組合 D</li>\n</ul>",
   "file": "2024_P1A_QU(CHI).md"
