   "text": "參照以下於溫度 T 時在一個體積 V 的密閉容器內的平衡體系：\n\nPCl₅(g) ⇌ PCl₃(g) + Cl₂(g)\n\n下列哪些變化會增加在體系中 PCl₃(g) 的摩爾數？\n\n(1) 把催化劑加進體系中。\n(2) 從體系中除去小量的 Cl₂(g)。\n(3) 於溫度 T 時增加體系的體積。\n\n- A. 只有 (1) 和 (2)\n- B. 只有 (1) 和 (3)\n- C. 只有 (2) 和 (3)\n- D. (1)、(2) 和 (3)",
   "html": "<p>參照以下於溫度 T 時在一個體積 V 的密閉容器內的平衡體系：</p>\n<p>PCl₅(g) ⇌ PCl₃(g) + Cl₂(g)</p>\n<p>下列哪些變化會增加在體系中 PCl₃(g) 的摩爾數？</p>\n<p>(1) 把催化劑加進體系中。\n(2) 從體系中除去小量的 Cl₂(g)。\n(3) 於溫度 T 時增加體系的體積。</p>\n<ul>\n<li>A. 只有 (1) 和 (2)</li>\n<li>B. 只有 (1) 和 (3)</li>\n<li>C. 只有 (2) 和 (3)</li>\n<li>D. (1)、(2) 和 (3)</li>\n</ul>",
