   "text": "某有機化合物具以下結構：\n\n![Q35 有機化合物結構](2024_P1A_crops/q35.png)\n\n下列哪些有關這化合物的陳述正確？\n\n(1) 它具有旋光性。\n(2) 它可溶於 NaOH(aq)。\n(3) 它具有一個醛官能基。\n\n- A. 只有 (1) 和 (2)\n- B. 只有 (1) 和 (3)\n- C. 只有 (2) 和 (3)\n- D. (1)、(2) 和 (3)",
   "html": "<p>某有機化合物具以下結構：</p>\n<p><img alt=\"Q35 有機化合物結構\" src=\"chem_2024_P1A_crops/q35.png\" /></p>\n<p>下列哪些有關這化合物的陳述正確？</p>\n<p>(1) 它具有旋光性。\n(2) 它可溶於 NaOH(aq)。\n(3) 它具有一個醛官能基。</p>\n<ul>\n<li>A. 只有 (1) 和 (2)</li>\n<li>B. 只有 (1) 和 (3)</li>\n<li>C. 只有 (2) 和 (3)</li>\n<li>D. (1)、(2) 和 (3)</li>\n</ul>",
