   "text": "考慮下列各陳述句並選出最佳的答案：\n\n第一陳述句：鐵在其化合物中展現可變的氧化態。\n第二陳述句：鐵生成有色的化合物。\n\n- A. 兩陳述句均正確，而第二陳述句是第一陳述句的合理解釋\n- B. 兩陳述句均正確，而第二陳述句並非第一陳述句的合理解釋\n- C. 第一陳述句錯誤，但第二陳述句正確\n- D. 兩陳述句均錯誤\n\n---\n\n*試卷完 —*\n\n## 待人工核對\n\n本卷為第 2 層文字交貨，由 easyocr（ch_tra+en，GPU）掃描底稿清洗而成；現模型無影像輸入，未能對頁影像覆核。以下題號建議第 3 層精修時對頁覆核：\n\n- 第 12 題：選項 V 的化學物種（V₂O₅／VO₂／VO／VO₃⁻）下標／離子形式待對頁核實。\n- 第 16 題：三原子的質量數（⁷²Ge、⁷³As、⁷⁴Se）待對頁核實。\n- 第 17 題：三個自由基步驟的化學式待對頁核實。\n- 第 9、19、22、26、28、32、33、35 題：圖為 300dpi 原卷截圖（程式定位＋墨跡覆蓋率校驗；無視覺覆核，位置／範圍待 spot-check）；第 3 層再換成向量重繪。",
   "html": "<p>考慮下列各陳述句並選出最佳的答案：</p>\n<p>第一陳述句：鐵在其化合物中展現可變的氧化態。\n第二陳述句：鐵生成有色的化合物。</p>\n<ul>\n<li>A. 兩陳述句均正確，而第二陳述句是第一陳述句的合理解釋</li>\n<li>B. 兩陳述句均正確，而第二陳述句並非第一陳述句的合理解釋</li>\n<li>C. 第一陳述句錯誤，但第二陳述句正確</li>\n<li>D. 兩陳述句均錯誤</li>\n</ul>\n<hr />\n<p><em>試卷完 —</em></p>\n<h2>待人工核對</h2>\n<p>本卷為第 2 層文字交貨，由 easyocr（ch_tra+en，GPU）掃描底稿清洗而成；現模型無影像輸入，未能對頁影像覆核。以下題號建議第 3 層精修時對頁覆核：</p>\n<ul>\n<li>第 12 題：選項 V 的化學物種（V₂O₅／VO₂／VO／VO₃⁻）下標／離子形式待對頁核實。</li>\n<li>第 16 題：三原子的質量數（⁷²Ge、⁷³As、⁷⁴Se）待對頁核實。</li>\n<li>第 17 題：三個自由基步驟的化學式待對頁核實。</li>\n<li>第 9、19、22、26、28、32、33、35 題：圖為 300dpi 原卷截圖（程式定位＋墨跡覆蓋率校驗；無視覺覆核，位置／範圍待 spot-check）；第 3 層再換成向量重繪。</li>\n</ul>",
