   "text": "(a)　碳在自然界存在著兩個穩定的同位素：¹²C 和 ¹³C。\n\n　　(i)　寫出 ¹²C 原子和 ¹³C 原子的一項不同之處。（1 分）\n\n　　(ii)　碳的相對原子質量是 12.011。假設碳只有兩個同位素 ¹²C 和 ¹³C，計算 ¹³C 的豐度百分率。（2 分）\n\n(b)　【題目內容待補：OCR 無法辨識，需對頁影像核實——原卷第 1 頁，疑為比較碳的同素異形體（石墨／鑽石）的結構與硬度差異】（3 分）\n\n(c)　C₂N₂ 是碳和氮的化合物，它含有一個碳-碳單鍵。繪出一個 C₂N₂ 分子的電子圖（只需顯示最外層的電子）。（1 分）",
