   "text": "利用以下各裝置進行了一個實驗來探究鐵鏽蝕的情況。\n\n![Q2 鐵鏽蝕裝置](2024_P1B_crops/q02.png)\n\nX、Y 和鐵是三種不同的金屬。一段時間後，在裝置 1 和裝置 2 都呈現粉紅色。然而，只有裝置 1 的鐵釘周圍呈現藍色。\n\n(a)　寫出導致鐵鏽蝕的各主要條件。\n\n(b)　提出在裝置 1 和裝置 2 中哪物種轉為粉紅色。（1 分）\n\n(c)　解釋為什麼裝置 1 的鐵釘周圍呈現藍色。（2 分）\n\n(d)　根據以上觀察，把該三種金屬（X、Y 和鐵）按其活性的遞減次序排列出來。解釋你的答案。（2 分）",
   "html": "<p>利用以下各裝置進行了一個實驗來探究鐵鏽蝕的情況。</p>\n<p><img alt=\"Q2 鐵鏽蝕裝置\" src=\"chem_2024_P1B_crops/q02.png\" /></p>\n<p>X、Y 和鐵是三種不同的金屬。一段時間後，在裝置 1 和裝置 2 都呈現粉紅色。然而，只有裝置 1 的鐵釘周圍呈現藍色。</p>\n<p>(a)　寫出導致鐵鏽蝕的各主要條件。</p>\n<p>(b)　提出在裝置 1 和裝置 2 中哪物種轉為粉紅色。（1 分）</p>\n<p>(c)　解釋為什麼裝置 1 的鐵釘周圍呈現藍色。（2 分）</p>\n<p>(d)　根據以上觀察，把該三種金屬（X、Y 和鐵）按其活性的遞減次序排列出來。解釋你的答案。（2 分）</p>",
