   "text": "下圖顯示一個化學電池的實驗裝置。電池中所使用的溶液都是 1.0 M，儀器 W 是用來量度該電池的電壓。\n\n![Q3 化學電池裝置](2024_P1B_crops/q03.png)\n\n(a)　提出儀器 W 是什麼。（1 分）\n\n(b)　提出鹽橋的一個功用。（1 分）\n\n(c)　在製備化學電池 1 的鹽橋時：\n\n　　(i)　解釋為什麼不可使用 KCl(aq)。（1 分）\n\n　　(ii)　提出一個可使用的適當溶液。（1 分）\n\n(d)　使用類似化學電池 1 的裝置來進行另外三個實驗。半電池則使用不同組合的電極和 1.0 M 溶液（CuSO₄(aq)、AgNO₃(aq)、ZnSO₄(aq) 和 MnSO₄(aq)）。下表顯示各化學電池的資料。\n\n| 化學電池 | 1 | 2 | 3 | 4 |\n|---|---|---|---|---|\n| 半電池 A | Cu(s)/Cu²⁺(aq) | Cu(s)/Cu²⁺(aq) | Cu(s)/Cu²⁺(aq) | Ag(s)/Ag⁺(aq) |\n| 半電池 B | Ag(s)/Ag⁺(aq) | Zn(s)/Zn²⁺(aq) | Mn(s)/Mn²⁺(aq) | Mn(s)/Mn²⁺(aq) |\n| 電壓 / V | −0.46 | +1.10 | +1.15 | y |\n\n　　(i)　參照化學電池 1、2 和 3，指出並解釋以上化學電池中使用的四種金屬，何者是最強的還原劑。（2 分）\n\n　　(ii)　計算 y 的預期值。（1 分）\n\n　　(iii)　寫出在化學電池 4 的陰極上所起變化的半反應式。（1 分）",
   "html": "<p>下圖顯示一個化學電池的實驗裝置。電池中所使用的溶液都是 1.0 M，儀器 W 是用來量度該電池的電壓。</p>\n<p><img alt=\"Q3 化學電池裝置\" src=\"chem_2024_P1B_crops/q03.png\" /></p>\n<p>(a)　提出儀器 W 是什麼。（1 分）</p>\n<p>(b)　提出鹽橋的一個功用。（1 分）</p>\n<p>(c)　在製備化學電池 1 的鹽橋時：</p>\n<p>(i)　解釋為什麼不可使用 KCl(aq)。（1 分）</p>\n<p>(ii)　提出一個可使用的適當溶液。（1 分）</p>\n<p>(d)　使用類似化學電池 1 的裝置來進行另外三個實驗。半電池則使用不同組合的電極和 1.0 M 溶液（CuSO₄(aq)、AgNO₃(aq)、ZnSO₄(aq) 和 MnSO₄(aq)）。下表顯示各化學電池的資料。</p>\n<table>\n<thead>\n<tr>\n<th>化學電池</th>\n<th>1</th>\n<th>2</th>\n<th>3</th>\n<th>4</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>半電池 A</td>\n<td>Cu(s)/Cu²⁺(aq)</td>\n<td>Cu(s)/Cu²⁺(aq)</td>\n<td>Cu(s)/Cu²⁺(aq)</td>\n<td>Ag(s)/Ag⁺(aq)</td>\n</tr>\n<tr>\n<td>半電池 B</td>\n<td>Ag(s)/Ag⁺(aq)</td>\n<td>Zn(s)/Zn²⁺(aq)</td>\n<td>Mn(s)/Mn²⁺(aq)</td>\n<td>Mn(s)/Mn²⁺(aq)</td>\n</tr>\n<tr>\n<td>電壓 / V</td>\n<td>−0.46</td>\n<td>+1.10</td>\n<td>+1.15</td>\n<td>y</td>\n</tr>\n</tbody>\n</table>\n<p>(i)　參照化學電池 1、2 和 3，指出並解釋以上化學電池中使用的四種金屬，何者是最強的還原劑。（2 分）</p>\n<p>(ii)　計算 y 的預期值。（1 分）</p>\n<p>(iii)　寫出在化學電池 4 的陰極上所起變化的半反應式。（1 分）</p>",
   "file": "2024_P1B_QU(CHI).md"
