   "text": "氨基磺酸（相對分子質量 = 97.1）可以用來清除水煲的水垢。水垢主要由 CaCO₃ 組成。\n\n(a)　(i)　按質量計，氨基磺酸只含 3.09% 的氫、14.42% 的氮、49.43% 的氧和 33.06% 的硫。通過計算，測定氨基磺酸的實驗式。（相對原子質量：H = 1.0，N = 14.0，O = 16.0，S = 32.1）（2 分）\n\n　　(ii)　推定氨基磺酸的分子式。（1 分）\n\n(b)　在一個實驗中，0.486 g 的氨基磺酸與 100.0 cm³ 的 0.150 M NaOH(aq)（其為過量的）反應。餘下的 NaOH(aq) 需用 24.80 cm³ 的 0.202 M H₂SO₄(aq) 完全中和。\n\n　　(i)　計算與該 H₂SO₄(aq) 反應了的 NaOH(aq) 的摩爾數。（1 分）\n\n　　(ii)　計算與該氨基磺酸反應了的 NaOH(aq) 的摩爾數。（1 分）\n\n　　(iii)　推定氨基磺酸的鹽基度。（1 分）\n\n(c)　寫出在水垢中的 CaCO₃(s) 與 H⁺(aq) 反應的離子方程式。（1 分）",
   "html": "<p>氨基磺酸（相對分子質量 = 97.1）可以用來清除水煲的水垢。水垢主要由 CaCO₃ 組成。</p>\n<p>(a)　(i)　按質量計，氨基磺酸只含 3.09% 的氫、14.42% 的氮、49.43% 的氧和 33.06% 的硫。通過計算，測定氨基磺酸的實驗式。（相對原子質量：H = 1.0，N = 14.0，O = 16.0，S = 32.1）（2 分）</p>\n<p>(ii)　推定氨基磺酸的分子式。（1 分）</p>\n<p>(b)　在一個實驗中，0.486 g 的氨基磺酸與 100.0 cm³ 的 0.150 M NaOH(aq)（其為過量的）反應。餘下的 NaOH(aq) 需用 24.80 cm³ 的 0.202 M H₂SO₄(aq) 完全中和。</p>\n<p>(i)　計算與該 H₂SO₄(aq) 反應了的 NaOH(aq) 的摩爾數。（1 分）</p>\n<p>(ii)　計算與該氨基磺酸反應了的 NaOH(aq) 的摩爾數。（1 分）</p>\n<p>(iii)　推定氨基磺酸的鹽基度。（1 分）</p>\n<p>(c)　寫出在水垢中的 CaCO₃(s) 與 H⁺(aq) 反應的離子方程式。（1 分）</p>",
