   "text": "把六種 0.1 M 的溶液分成兩組如下：\n\n| A 組 | B 組 |\n|---|---|\n| NH₃(aq) | Na₂CO₃(aq) |\n| Mg(NO₃)₂(aq) | FeSO₄(aq) |\n| H₂SO₄(aq) | FeCl₃(aq) |\n\n把 A 組的一種溶液與 B 組的一種溶液混合。\n\n(a)　(i)　哪兩種溶液混合時可得出綠色沉澱物？（1 分）\n\n　　(ii)　寫出在 (a)(i) 提及的綠色沉澱物的名稱。（1 分）\n\n(b)　(i)　哪兩種溶液混合時可得出白色沉澱物？（1 分）\n\n　　(ii)　寫出生成在 (b)(i) 提及的白色沉澱物的離子方程式。（1 分）\n\n(c)　哪兩種溶液混合時可釋出氣泡？（1 分）",
   "html": "<p>把六種 0.1 M 的溶液分成兩組如下：</p>\n<table>\n<thead>\n<tr>\n<th>A 組</th>\n<th>B 組</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>NH₃(aq)</td>\n<td>Na₂CO₃(aq)</td>\n</tr>\n<tr>\n<td>Mg(NO₃)₂(aq)</td>\n<td>FeSO₄(aq)</td>\n</tr>\n<tr>\n<td>H₂SO₄(aq)</td>\n<td>FeCl₃(aq)</td>\n</tr>\n</tbody>\n</table>\n<p>把 A 組的一種溶液與 B 組的一種溶液混合。</p>\n<p>(a)　(i)　哪兩種溶液混合時可得出綠色沉澱物？（1 分）</p>\n<p>(ii)　寫出在 (a)(i) 提及的綠色沉澱物的名稱。（1 分）</p>\n<p>(b)　(i)　哪兩種溶液混合時可得出白色沉澱物？（1 分）</p>\n<p>(ii)　寫出生成在 (b)(i) 提及的白色沉澱物的離子方程式。（1 分）</p>\n<p>(c)　哪兩種溶液混合時可釋出氣泡？（1 分）</p>",
