   "text": "(a)　(i)　繪出一個二氯甲烷分子的三維結構。（1 分）\n\n　　(ii)　解釋二氯甲烷分子內的各鍵是否具極性。（2 分）\n\n　　(iii)　解釋二氯甲烷分子是否具極性。（1 分）\n\n(b)　解釋為什麼二氯甲烷的沸點較乙醇的低。（2 分）",
   "html": "<p>(a)　(i)　繪出一個二氯甲烷分子的三維結構。（1 分）</p>\n<p>(ii)　解釋二氯甲烷分子內的各鍵是否具極性。（2 分）</p>\n<p>(iii)　解釋二氯甲烷分子是否具極性。（1 分）</p>\n<p>(b)　解釋為什麼二氯甲烷的沸點較乙醇的低。（2 分）</p>",
