   "text": "參照以下涉及五個有機化合物 P、Q、R、S 和 T 的轉化。\n\n![Q11 有機轉化圖](2024_P1B_crops/q11.png)\n\n(a)　提出由 P 轉化為 Q 所需用的（各）試劑和（各）反應條件。（1 分）\n\n(b)　寫出由 Q 轉化為 R 所涉及的反應類別。（1 分）\n\n(c)　繪出 R 的結構。（1 分）\n\n(d)　繪出 S 的結構。（1 分）\n\n(e)　在 Q、R、S 和 T 四個有機化合物中，寫出哪兩個能夠在適當條件下與 KMnO₄(aq) 發生反應，並繪出各自生成的有機產物的結構。（3 分）",
   "html": "<p>參照以下涉及五個有機化合物 P、Q、R、S 和 T 的轉化。</p>\n<p><img alt=\"Q11 有機轉化圖\" src=\"chem_2024_P1B_crops/q11.png\" /></p>\n<p>(a)　提出由 P 轉化為 Q 所需用的（各）試劑和（各）反應條件。（1 分）</p>\n<p>(b)　寫出由 Q 轉化為 R 所涉及的反應類別。（1 分）</p>\n<p>(c)　繪出 R 的結構。（1 分）</p>\n<p>(d)　繪出 S 的結構。（1 分）</p>\n<p>(e)　在 Q、R、S 和 T 四個有機化合物中，寫出哪兩個能夠在適當條件下與 KMnO₄(aq) 發生反應，並繪出各自生成的有機產物的結構。（3 分）</p>",
   "file": "2024_P1B_QU(CHI).md"
