   "text": "一個有機化合物 Z 能夠被濃 NaOH(aq) 水解生成產物 A 和產物 B。產物 B 具有清潔性質。Z 的結構如下所示：\n\n![Q12 化合物 Z 結構](2024_P1B_crops/q12.png)\n\n(a)　寫出產物 A 的系統名稱。（1 分）\n\n(b)　繪出產物 B 的結構。（1 分）\n\n(c)　(i)　把產物 B 加入油-水混合物中搖動。除了產生泡沫，提出另一項預期的觀察。（1 分）\n\n　　(ii)　根據產物 B 的結構，解釋你在 (c)(i) 提出的觀察。（2 分）",
   "html": "<p>一個有機化合物 Z 能夠被濃 NaOH(aq) 水解生成產物 A 和產物 B。產物 B 具有清潔性質。Z 的結構如下所示：</p>\n<p><img alt=\"Q12 化合物 Z 結構\" src=\"chem_2024_P1B_crops/q12.png\" /></p>\n<p>(a)　寫出產物 A 的系統名稱。（1 分）</p>\n<p>(b)　繪出產物 B 的結構。（1 分）</p>\n<p>(c)　(i)　把產物 B 加入油-水混合物中搖動。除了產生泡沫，提出另一項預期的觀察。（1 分）</p>\n<p>(ii)　根據產物 B 的結構，解釋你在 (c)(i) 提出的觀察。（2 分）</p>",
