   "text": "在以下化學平衡體系中，當加入 NaCl(s) 或提升溫度，平衡混合物在這兩種情況都有可觀察的變化：\n\nCo²⁺(aq) + 4Cl⁻(aq) ⇌ CoCl₄²⁻(aq)　粉紅色　藍色　ΔH > 0\n\n考慮上述兩種情況對體系的平衡位置和平衡常數的影響，寫出並解釋在這兩種情況下的預期可觀察的變化。（6 分）\n\n---\n\n*試卷完 —*\n\n## 待人工核對\n\n本卷為第 2 層文字交貨，由 easyocr（ch_tra+en，GPU）掃描底稿清洗而成；現模型無影像輸入，未能對頁影像覆核。以下題號建議第 3 層精修時對頁覆核：\n\n- 第 1(b) 題：OCR 完全無法辨識，題幹內容待對頁補回（原卷第 1 頁）。\n- 第 1、2 題：部分小題之分數（分）標記待對頁核實。\n- 第 3(d)、8 題：表格欄位（電極組合／實驗編號）已按結構重整，待對頁核實列序。\n- 第 2、3、5、10、11、12 題：圖為 300dpi 原卷截圖（程式定位＋墨跡覆蓋率校驗；無視覺覆核，位置／範圍待 spot-check）；第 3 層再換成向量重繪。",
   "html": "<p>在以下化學平衡體系中，當加入 NaCl(s) 或提升溫度，平衡混合物在這兩種情況都有可觀察的變化：</p>\n<p>Co²⁺(aq) + 4Cl⁻(aq) ⇌ CoCl₄²⁻(aq)　粉紅色　藍色　ΔH &gt; 0</p>\n<p>考慮上述兩種情況對體系的平衡位置和平衡常數的影響，寫出並解釋在這兩種情況下的預期可觀察的變化。（6 分）</p>\n<hr />\n<p><em>試卷完 —</em></p>\n<h2>待人工核對</h2>\n<p>本卷為第 2 層文字交貨，由 easyocr（ch_tra+en，GPU）掃描底稿清洗而成；現模型無影像輸入，未能對頁影像覆核。以下題號建議第 3 層精修時對頁覆核：</p>\n<ul>\n<li>第 1(b) 題：OCR 完全無法辨識，題幹內容待對頁補回（原卷第 1 頁）。</li>\n<li>第 1、2 題：部分小題之分數（分）標記待對頁核實。</li>\n<li>第 3(d)、8 題：表格欄位（電極組合／實驗編號）已按結構重整，待對頁核實列序。</li>\n<li>第 2、3、5、10、11、12 題：圖為 300dpi 原卷截圖（程式定位＋墨跡覆蓋率校驗；無視覺覆核，位置／範圍待 spot-check）；第 3 層再換成向量重繪。</li>\n</ul>",
