   "text": "回答試題的所有部分。\n\n(a)　硫酸銨是由氨衍生出來的化合物。\n\n　　(i)　寫出生產氨的工業過程名稱。（1 分）\n\n　　(ii)　解釋硫酸銨如何能紓緩世界糧食不足的問題。（1 分）\n\n(b)　在氯鹼工業使用膜電解池和流汞電解池來生產氯。\n\n　　(i)　流汞電解池使用的原理是什麼？（1 分）\n\n　　(ii)　寫出在氯鹼工業使用膜電解池較流汞電解池的一個優點。（1 分）\n\n(c)　在有酵母的情況下，把糖發酵可以生產含酒精飲料。寫出酵母在糖發酵中的功用。（1 分）\n\n(d)　以下兩個方法都可以製造乙酸：\n\n方法 1：\n\n2CH₃(CH₂)₂CH₃ + 5O₂ → 4CH₃COOH + 2H₂O\n\n方法 2（涉及三個步驟的反應）：\n\n步驟 (i)：CH₃OH + HI → CH₃I + H₂O（這反應是放熱的）\n步驟 (ii)：CH₃I + CO → CH₃COI\n步驟 (iii)：CH₃COI + H₂O → CH₃COOH + HI\n\n| 反應條件 | 方法 1 | 方法 2 |\n|---|---|---|\n| 溫度／壓強 | 110–120 °C 和 60 atm | 150–200 °C 和 30–60 atm |\n| 催化劑 | 乙酸鈷(II) | 銠化合物 [?] |\n\n　　(i)　繪出方法 1 所涉反應的經催化反應的能量曲線圖，標示各坐標軸。（2 分）\n\n\n　　(ii)　根據所示的方程式，計算方法 1 的原子經濟。（相對分子質量：CH₃(CH₂)₂CH₃ = 58.0，O₂ = 32.0，CH₃COOH = 60.0，H₂O = 18.0）（1 分）\n\n　　(iii)　寫出方法 2 所涉及的總反應的化學方程式。（1 分）\n\n　　(iv)　根據所提供的資料，提出一個原因為什麼 HI 在方法 2 中亦可被視為催化劑。（1 分）\n\n　　(v)　根據所提供的資料及綠色化學的原理，提出一個原因為什麼有些人認為方法 1 比方法 2 可被視為較「綠色」。（1 分）\n\n　　(vi)　[?]方法 2 比方法 1 可被視為較「綠色」。（1 分）\n\n(e)　(i)　以下是 N₂O₅(g) 的分解的方程式：\n\n2N₂O₅(g) → 4NO₂(g) + O₂(g)\n\n提出如何能跟蹤這分解的進度。（1 分）\n\n　　(ii)　這分解的速率方程如下所示：\n\n速率 = k[N₂O₅(g)]ᵃ\n\n其中 k 是速率常數，a 是對應 N₂O₅(g) 的反應級數。已知在 318 K 這分解的速率常數是 4.29 × 10⁻⁵ s⁻¹。\n\n(1)　a 的數值是什麼？（1 分）\n\n(2)　這分解的活化能是 108.5 kJ mol⁻¹。計算這分解在 338 K 的速率常數。（氣體常數 R = 8.31 J K⁻¹ mol⁻¹；阿列紐斯方程：log k = 常數 − Ea/(2.303RT)）（2 分）\n\n　　(iii)　以下坐標圖顯示一個 N₂O₅(g) 樣本在溫度 T 時的麥克斯韋-玻爾茲曼分佈曲線。\n\n![Q1(e) 麥克斯韋-玻爾茲曼分佈曲線（溫度 T）](2024_P2_crops/q1e_a.png)\n\n(1)　以下坐標圖中的曲線 A、B 和 C，何者可以表示同一的 N₂O₅(g) 樣本在溫度高於 T 時的麥克斯韋-玻爾茲曼分佈曲線？（1 分）\n\n![Q1(e) 曲線 A、B、C](2024_P2_crops/q1e_b.png)\n\n(2)　利用麥克斯韋-玻爾茲曼分佈曲線，解釋為什麼提升溫度會使氣相反應的反應速率增加。（2 分）",
   "html": "<p>回答試題的所有部分。</p>\n<p>(a)　硫酸銨是由氨衍生出來的化合物。</p>\n<p>(i)　寫出生產氨的工業過程名稱。（1 分）</p>\n<p>(ii)　解釋硫酸銨如何能紓緩世界糧食不足的問題。（1 分）</p>\n<p>(b)　在氯鹼工業使用膜電解池和流汞電解池來生產氯。</p>\n<p>(i)　流汞電解池使用的原理是什麼？（1 分）</p>\n<p>(ii)　寫出在氯鹼工業使用膜電解池較流汞電解池的一個優點。（1 分）</p>\n<p>(c)　在有酵母的情況下，把糖發酵可以生產含酒精飲料。寫出酵母在糖發酵中的功用。（1 分）</p>\n<p>(d)　以下兩個方法都可以製造乙酸：</p>\n<p>方法 1：</p>\n<p>2CH₃(CH₂)₂CH₃ + 5O₂ → 4CH₃COOH + 2H₂O</p>\n<p>方法 2（涉及三個步驟的反應）：</p>\n<p>步驟 (i)：CH₃OH + HI → CH₃I + H₂O（這反應是放熱的）\n步驟 (ii)：CH₃I + CO → CH₃COI\n步驟 (iii)：CH₃COI + H₂O → CH₃COOH + HI</p>\n<table>\n<thead>\n<tr>\n<th>反應條件</th>\n<th>方法 1</th>\n<th>方法 2</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>溫度／壓強</td>\n<td>110–120 °C 和 60 atm</td>\n<td>150–200 °C 和 30–60 atm</td>\n</tr>\n<tr>\n<td>催化劑</td>\n<td>乙酸鈷(II)</td>\n<td>銠化合物 [?]</td>\n</tr>\n</tbody>\n</table>\n<p>(i)　繪出方法 1 所涉反應的經催化反應的能量曲線圖，標示各坐標軸。（2 分）</p>\n<p>(ii)　根據所示的方程式，計算方法 1 的原子經濟。（相對分子質量：CH₃(CH₂)₂CH₃ = 58.0，O₂ = 32.0，CH₃COOH = 60.0，H₂O = 18.0）（1 分）</p>\n<p>(iii)　寫出方法 2 所涉及的總反應的化學方程式。（1 分）</p>\n<p>(iv)　根據所提供的資料，提出一個原因為什麼 HI 在方法 2 中亦可被視為催化劑。（1 分）</p>\n<p>(v)　根據所提供的資料及綠色化學的原理，提出一個原因為什麼有些人認為方法 1 比方法 2 可被視為較「綠色」。（1 分）</p>\n<p>(vi)　[?]方法 2 比方法 1 可被視為較「綠色」。（1 分）</p>\n<p>(e)　(i)　以下是 N₂O₅(g) 的分解的方程式：</p>\n<p>2N₂O₅(g) → 4NO₂(g) + O₂(g)</p>\n<p>提出如何能跟蹤這分解的進度。（1 分）</p>\n<p>(ii)　這分解的速率方程如下所示：</p>\n<p>速率 = k[N₂O₅(g)]ᵃ</p>\n<p>其中 k 是速率常數，a 是對應 N₂O₅(g) 的反應級數。已知在 318 K 這分解的速率常數是 4.29 × 10⁻⁵ s⁻¹。</p>\n<p>(1)　a 的數值是什麼？（1 分）</p>\n<p>(2)　這分解的活化能是 108.5 kJ mol⁻¹。計算這分解在 338 K 的速率常數。（氣體常數 R = 8.31 J K⁻¹ mol⁻¹；阿列紐斯方程：log k = 常數 − Ea/(2.303RT)）（2 分）</p>\n<p>(iii)　以下坐標圖顯示一個 N₂O₅(g) 樣本在溫度 T 時的麥克斯韋-玻爾茲曼分佈曲線。</p>\n<p><img alt=\"Q1(e) 麥克斯韋-玻爾茲曼分佈曲線（溫度 T）\" src=\"chem_2024_P2_crops/q1e_a.png\" /></p>\n<p>(1)　以下坐標圖中的曲線 A、B 和 C，何者可以表示同一的 N₂O₅(g) 樣本在溫度高於 T 時的麥克斯韋-玻爾茲曼分佈曲線？（1 分）</p>\n<p><img alt=\"Q1(e) 曲線 A、B、C\" src=\"chem_2024_P2_crops/q1e_b.png\" /></p>\n<p>(2)　利用麥克斯韋-玻爾茲曼分佈曲線，解釋為什麼提升溫度會使氣相反應的反應速率增加。（2 分）</p>",
