   "text": "回答試題的所有部分。\n\n(a)　橡皮筋是以硫化橡膠製成。當把橡皮筋扯伸，然後鬆開，它便能夠回復原狀。根據分子結構，解釋橡皮筋的彈性。（2 分）\n\n(b)　甲殼素是龍蝦的外骨骼組分。甲殼素的部分結構顯示如下：\n\n![Q2(b) 甲殼素結構](2024_P2_crops/q2b.png)\n\n　　(i)　X 是什麼？（1 分）\n\n　　(ii)　根據甲殼素的結構，解釋為什麼甲殼素與龍蝦外骨骼的硬度有關。（1 分）\n\n　　(iii)　寫出一種液晶相的名稱，其中各分子向著同一方向排列，並且互相對齊成一直線。（1 分）\n\n(c)　聚乳酸 (PLA) 是一種合成的生物材料。參考以下有關 PLA 的資料：\n\n| 結構 | 聚合物類別 | 原料 | 用途 |\n|---|---|---|---|\n| ![PLA 結構](2024_P2_crops/q2c.png) | 縮合聚合物 | 玉米澱粉 | 縫合傷口的手術線 |\n\n　　(i)　寫出 PLA 的官能基。（1 分）\n\n　　(ii)　繪出 PLA 的單體的結構。（1 分）\n\n　　(iii)　提出為什麼 PLA 被分類為縮合聚合物。（1 分）\n\n　　(iv)　根據綠色化學原理，解釋為什麼使用玉米澱粉作為原料來生產 PLA 是對環境友善。（1 分）\n\n　　(v)　寫出一項 PLA 適合作為手術線的一個性質。（1 分）\n\n　　(vi)　PLA 亦可用來製造即棄杯子。解釋是否適合使用壓塑注射來製造 PLA 即棄杯子。（1 分）\n\n　　(vii)　提出一個原因為什麼 PLA 溶於乙酸乙酯，卻不溶於己烷。（1 分）\n\n(d)　在恆壓而溫度不相同時，鐵的各晶體結構如下所示：\n\n| 溫度 | 晶體結構 |\n|---|---|\n| 低於 912 °C | 體心立方 |\n| 912 °C – 1394 °C | 立方緊密堆填 |\n| 1394 °C – 1538 °C | 體心立方 |\n\n　　(i)　在 25 °C 時，晶體結構中鐵原子的配位數是多少？（1 分）\n\n　　(ii)　在 1000 °C 時，鐵具有立方緊密堆填晶體結構。\n\n(1)　繪出在 1000 °C 時鐵晶體的一個晶胞。（1 分）\n\n\n(2)　在這晶體結構中，鐵原子是怎樣排列的？（1 分）\n\n　　(iii)　鑑於鐵在 25 °C 和 1450 °C 的晶體結構是相同的，一名學生推定在這兩個溫度下鐵的密度是相同的。解釋這個推定是否正確。（1 分）\n\n　　(iv)　凱夫拉 [?]（Kevlar）和尼龍-6,6 在室溫下的一些資料列表如下：\n\n| | 凱夫拉 [?] | 尼龍-6,6 |\n|---|---|---|\n| 相對拉伸強度 | 5.1 | 1.17 [?] |\n| 密度 / g cm⁻³ | 1.44 | 1.14 |\n| 導熱性能 | 良好 | 不良 |\n\n(1)　用以上哪一物料來製造避彈衣是較佳之選？根據所提供的資料，提出兩個原因來解釋你的答案。（2 分）\n\n(2)　凱夫拉 [?] 和尼龍-6,6 都是聚醯胺。提出兩個原因為什麼凱夫拉 [?] 較尼龍-6,6 具有更高的剛性。（2 分）",
   "html": "<p>回答試題的所有部分。</p>\n<p>(a)　橡皮筋是以硫化橡膠製成。當把橡皮筋扯伸，然後鬆開，它便能夠回復原狀。根據分子結構，解釋橡皮筋的彈性。（2 分）</p>\n<p>(b)　甲殼素是龍蝦的外骨骼組分。甲殼素的部分結構顯示如下：</p>\n<p><img alt=\"Q2(b) 甲殼素結構\" src=\"chem_2024_P2_crops/q2b.png\" /></p>\n<p>(i)　X 是什麼？（1 分）</p>\n<p>(ii)　根據甲殼素的結構，解釋為什麼甲殼素與龍蝦外骨骼的硬度有關。（1 分）</p>\n<p>(iii)　寫出一種液晶相的名稱，其中各分子向著同一方向排列，並且互相對齊成一直線。（1 分）</p>\n<p>(c)　聚乳酸 (PLA) 是一種合成的生物材料。參考以下有關 PLA 的資料：</p>\n<table>\n<thead>\n<tr>\n<th>結構</th>\n<th>聚合物類別</th>\n<th>原料</th>\n<th>用途</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><img alt=\"PLA 結構\" src=\"chem_2024_P2_crops/q2c.png\" /></td>\n<td>縮合聚合物</td>\n<td>玉米澱粉</td>\n<td>縫合傷口的手術線</td>\n</tr>\n</tbody>\n</table>\n<p>(i)　寫出 PLA 的官能基。（1 分）</p>\n<p>(ii)　繪出 PLA 的單體的結構。（1 分）</p>\n<p>(iii)　提出為什麼 PLA 被分類為縮合聚合物。（1 分）</p>\n<p>(iv)　根據綠色化學原理，解釋為什麼使用玉米澱粉作為原料來生產 PLA 是對環境友善。（1 分）</p>\n<p>(v)　寫出一項 PLA 適合作為手術線的一個性質。（1 分）</p>\n<p>(vi)　PLA 亦可用來製造即棄杯子。解釋是否適合使用壓塑注射來製造 PLA 即棄杯子。（1 分）</p>\n<p>(vii)　提出一個原因為什麼 PLA 溶於乙酸乙酯，卻不溶於己烷。（1 分）</p>\n<p>(d)　在恆壓而溫度不相同時，鐵的各晶體結構如下所示：</p>\n<table>\n<thead>\n<tr>\n<th>溫度</th>\n<th>晶體結構</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>低於 912 °C</td>\n<td>體心立方</td>\n</tr>\n<tr>\n<td>912 °C – 1394 °C</td>\n<td>立方緊密堆填</td>\n</tr>\n<tr>\n<td>1394 °C – 1538 °C</td>\n<td>體心立方</td>\n</tr>\n</tbody>\n</table>\n<p>(i)　在 25 °C 時，晶體結構中鐵原子的配位數是多少？（1 分）</p>\n<p>(ii)　在 1000 °C 時，鐵具有立方緊密堆填晶體結構。</p>\n<p>(1)　繪出在 1000 °C 時鐵晶體的一個晶胞。（1 分）</p>\n<p>(2)　在這晶體結構中，鐵原子是怎樣排列的？（1 分）</p>\n<p>(iii)　鑑於鐵在 25 °C 和 1450 °C 的晶體結構是相同的，一名學生推定在這兩個溫度下鐵的密度是相同的。解釋這個推定是否正確。（1 分）</p>\n<p>(iv)　凱夫拉 [?]（Kevlar）和尼龍-6,6 在室溫下的一些資料列表如下：</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>凱夫拉 [?]</th>\n<th>尼龍-6,6</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>相對拉伸強度</td>\n<td>5.1</td>\n<td>1.17 [?]</td>\n</tr>\n<tr>\n<td>密度 / g cm⁻³</td>\n<td>1.44</td>\n<td>1.14</td>\n</tr>\n<tr>\n<td>導熱性能</td>\n<td>良好</td>\n<td>不良</td>\n</tr>\n</tbody>\n</table>\n<p>(1)　用以上哪一物料來製造避彈衣是較佳之選？根據所提供的資料，提出兩個原因來解釋你的答案。（2 分）</p>\n<p>(2)　凱夫拉 [?] 和尼龍-6,6 都是聚醯胺。提出兩個原因為什麼凱夫拉 [?] 較尼龍-6,6 具有更高的剛性。（2 分）</p>",
