   "text": "登革熱是由登革病毒（DENV）所引起的感染。在很多熱帶和亞熱帶國家，這是一種風土病。DENV 包括四種不同的亞型，每種亞型都能導致登革熱。\n\n(a) 登革熱的傳播途徑是什麼？（1 分）\n\n(b) 提出在熱帶和亞熱帶地區的兩個環境因素，會令這些地區內居民感染登革熱的風險較高，並加以解釋。（3 分）\n\n(c) (i) 參考患者在沒有接受任何治療下，於受某種亞型的 DENV 感染後康復的過程，寫出令患者康復的三種白血細胞，並分別描述它們各自的作用。（3 分）\n\n(ii) 解釋為什麼曾受某種亞型的 DENV 感染的康復者，日後仍可受其他亞型的 DENV 感染。（2 分）\n\n(d) 提出對抗登革熱傳播的一項預防措施。（1 分）",
   "html": "<p>登革熱是由登革病毒（DENV）所引起的感染。在很多熱帶和亞熱帶國家，這是一種風土病。DENV 包括四種不同的亞型，每種亞型都能導致登革熱。</p>\n<p>(a) 登革熱的傳播途徑是什麼？（1 分）</p>\n<p>(b) 提出在熱帶和亞熱帶地區的兩個環境因素，會令這些地區內居民感染登革熱的風險較高，並加以解釋。（3 分）</p>\n<p>(c) (i) 參考患者在沒有接受任何治療下，於受某種亞型的 DENV 感染後康復的過程，寫出令患者康復的三種白血細胞，並分別描述它們各自的作用。（3 分）</p>\n<p>(ii) 解釋為什麼曾受某種亞型的 DENV 感染的康復者，日後仍可受其他亞型的 DENV 感染。（2 分）</p>\n<p>(d) 提出對抗登革熱傳播的一項預防措施。（1 分）</p>",
