   "text": "（參考第 5 題的示意圖。）\n\n以下哪圖正確配對這個細胞的 DNA 含量在細胞週期的三個階段的變化？\n\n- A.\n\n![圖](2023_P1_crops/q06_a.png)\n\n- B.\n\n![圖](2023_P1_crops/q06_b.png)\n\n- C.\n\n![圖](2023_P1_crops/q06_c.png)\n\n- D.\n\n![圖](2023_P1_crops/q06_d.png)",
