   "text": "色盲是一種遺傳缺陷，因視網膜上的視錐細胞出現功能缺失所致。色盲有很多類型，例如紅綠色盲的人士不能區分紅色與綠色，而全色盲的人士則完全失去色覺。\n\n(a) 根據視錐細胞的功能，提出為什麼紅綠色盲的情況有別於全色盲。（1 分）\n\n(b) 紅綠色盲是由 X 染色體上一個隱性等位基因引起，全色盲則由位於某條常染色體上的一個隱性等位基因所導致。下表展示紅綠色盲和全色盲在男性和女性的發生率：\n\n| 色盲類型 | 男性 | 女性 |\n|---|---|---|\n| 紅綠色盲 | 8% | 0.5% |\n| 全色盲 | 0.00001% | 0.00001% |\n\n參考兩種色盲的遺傳，提出為什麼紅綠色盲在男性和女性發生的比率有別於全色盲。（4 分）\n\n(c) (i) 以下譜系顯示紅綠色盲在某家庭內的遺傳：\n\n![圖](2023_P1_crops/b6.png)\n\n該對夫婦將生育多一名子女。以 B 代表正常色覺的等位基因，b 代表紅綠色盲的等位基因，繪畫一遺傳圖，並計算該名新生嬰兒是紅綠色盲的女孩的機會率。（4 分）\n\n（註：不接受龐氏表作為答案。）\n\n(ii) 個體 4 和 5 是雙生兒。你能否判斷他們是單卵雙生，還是二卵雙生？解釋你的答案。（2 分）",
   "html": "<p>色盲是一種遺傳缺陷，因視網膜上的視錐細胞出現功能缺失所致。色盲有很多類型，例如紅綠色盲的人士不能區分紅色與綠色，而全色盲的人士則完全失去色覺。</p>\n<p>(a) 根據視錐細胞的功能，提出為什麼紅綠色盲的情況有別於全色盲。（1 分）</p>\n<p>(b) 紅綠色盲是由 X 染色體上一個隱性等位基因引起，全色盲則由位於某條常染色體上的一個隱性等位基因所導致。下表展示紅綠色盲和全色盲在男性和女性的發生率：</p>\n<table>\n<thead>\n<tr>\n<th>色盲類型</th>\n<th>男性</th>\n<th>女性</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>紅綠色盲</td>\n<td>8%</td>\n<td>0.5%</td>\n</tr>\n<tr>\n<td>全色盲</td>\n<td>0.00001%</td>\n<td>0.00001%</td>\n</tr>\n</tbody>\n</table>\n<p>參考兩種色盲的遺傳，提出為什麼紅綠色盲在男性和女性發生的比率有別於全色盲。（4 分）</p>\n<p>(c) (i) 以下譜系顯示紅綠色盲在某家庭內的遺傳：</p>\n<p><img alt=\"圖\" src=\"bio_2023_P1_crops/b6.png\" /></p>\n<p>該對夫婦將生育多一名子女。以 B 代表正常色覺的等位基因，b 代表紅綠色盲的等位基因，繪畫一遺傳圖，並計算該名新生嬰兒是紅綠色盲的女孩的機會率。（4 分）</p>\n<p>（註：不接受龐氏表作為答案。）</p>\n<p>(ii) 個體 4 和 5 是雙生兒。你能否判斷他們是單卵雙生，還是二卵雙生？解釋你的答案。（2 分）</p>",
