   "text": "參考下圖，解答第 7 和 8 題。下圖顯示用以探究酵母呼吸速率的裝置：\n\n![圖](2023_P1_crops/q07_08.png)\n\n以下哪文字方程式正確顯示所探究的反應？\n\n- A. 葡萄糖 → 二氧化碳 + 水\n- B. 葡萄糖 → 二氧化碳 + 乙醇\n- C. 葡萄糖 + 氧 → 二氧化碳 + 水\n- D. 葡萄糖 + 氧 → 二氧化碳 + 乙醇",
