   "text": "一項近期的調查顯示，在本港多處發現溫室蟾這外來物種。有人認為溫室蟾可能對盧氏小樹蛙這本地瀕危物種構成威脅，因而引起關注。\n\n(a) 下表提供有關兩個青蛙物種的一些資料：\n\n| 項目 | 盧氏小樹蛙 | 溫室蟾 |\n|---|---|---|\n| 大小 | 1.5–2.5 cm | 1.2–3.0 cm |\n| 繁殖地點和生境 | 森林地、灌木叢、農地、市區公園 | 濕地、小型和暫時性水體、森林地、灌木叢、園圃 |\n| 食物 | 小型昆蟲 | 小型昆蟲和蝸牛 |\n\n比較兩個青蛙物種的生態位，提供兩項證據以支持溫室蟾可能對盧氏小樹蛙構成威脅，解釋你的答案。（3 分）\n\n(b) 以下地圖顯示兩個青蛙物種在香港的分布情況：\n\n![圖](2023_P1_crops/b7.png)\n\n提出為什麼以上資料不能證實盧氏小樹蛙真正受到溫室蟾威脅。（1 分）\n\n(c) 提出你可如何搜集數據，以顯示盧氏小樹蛙是否真正受溫室蟾影響。（2 分）",
   "html": "<p>一項近期的調查顯示，在本港多處發現溫室蟾這外來物種。有人認為溫室蟾可能對盧氏小樹蛙這本地瀕危物種構成威脅，因而引起關注。</p>\n<p>(a) 下表提供有關兩個青蛙物種的一些資料：</p>\n<table>\n<thead>\n<tr>\n<th>項目</th>\n<th>盧氏小樹蛙</th>\n<th>溫室蟾</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>大小</td>\n<td>1.5–2.5 cm</td>\n<td>1.2–3.0 cm</td>\n</tr>\n<tr>\n<td>繁殖地點和生境</td>\n<td>森林地、灌木叢、農地、市區公園</td>\n<td>濕地、小型和暫時性水體、森林地、灌木叢、園圃</td>\n</tr>\n<tr>\n<td>食物</td>\n<td>小型昆蟲</td>\n<td>小型昆蟲和蝸牛</td>\n</tr>\n</tbody>\n</table>\n<p>比較兩個青蛙物種的生態位，提供兩項證據以支持溫室蟾可能對盧氏小樹蛙構成威脅，解釋你的答案。（3 分）</p>\n<p>(b) 以下地圖顯示兩個青蛙物種在香港的分布情況：</p>\n<p><img alt=\"圖\" src=\"bio_2023_P1_crops/b7.png\" /></p>\n<p>提出為什麼以上資料不能證實盧氏小樹蛙真正受到溫室蟾威脅。（1 分）</p>\n<p>(c) 提出你可如何搜集數據，以顯示盧氏小樹蛙是否真正受溫室蟾影響。（2 分）</p>",
