   "text": "鯨死亡後，屍體會下沉至海底。屍體會支持一個稱為鯨落群落的獨特群落。\n\n(a) (i) 下圖顯示海洋的不同區域和鯨屍的位置：\n\n![圖](2023_P1_crops/b8a.png)\n\n參考生態系中的能量流，貯藏在鯨屍的能量的最終來源是什麼？（1 分）\n\n(ii) 參考上圖，解釋鯨屍對於在海洋底部的鯨落群落的重要性。（2 分）\n\n(b) 以鯨屍的軟組織作為食物的生物，在物質循環中的角色是什麼？（1 分）\n\n(c) 鯨屍的軟組織被移除後，另一組生物開始攝取骨骼內剩餘的營養素。一條中等體型的鯨，在骨骼內可能貯藏 2000–3000 kg 的脂質。以下棒形圖顯示在不同時段，在鯨骨骼上攝食的不同物種的豐度：\n\n![圖](2023_P1_crops/b8b.png)\n\n引用棒形圖中可支持上述個案屬生態演替例子的證據，完成下表。（4 分）\n\n| 生態演替的特徵 | 引自棒形圖中的證據 |\n|---|---|\n| 物種組成的改變 | ＿＿＿ |\n| 物種多樣性的改變 | ＿＿＿ |",
   "html": "<p>鯨死亡後，屍體會下沉至海底。屍體會支持一個稱為鯨落群落的獨特群落。</p>\n<p>(a) (i) 下圖顯示海洋的不同區域和鯨屍的位置：</p>\n<p><img alt=\"圖\" src=\"bio_2023_P1_crops/b8a.png\" /></p>\n<p>參考生態系中的能量流，貯藏在鯨屍的能量的最終來源是什麼？（1 分）</p>\n<p>(ii) 參考上圖，解釋鯨屍對於在海洋底部的鯨落群落的重要性。（2 分）</p>\n<p>(b) 以鯨屍的軟組織作為食物的生物，在物質循環中的角色是什麼？（1 分）</p>\n<p>(c) 鯨屍的軟組織被移除後，另一組生物開始攝取骨骼內剩餘的營養素。一條中等體型的鯨，在骨骼內可能貯藏 2000–3000 kg 的脂質。以下棒形圖顯示在不同時段，在鯨骨骼上攝食的不同物種的豐度：</p>\n<p><img alt=\"圖\" src=\"bio_2023_P1_crops/b8b.png\" /></p>\n<p>引用棒形圖中可支持上述個案屬生態演替例子的證據，完成下表。（4 分）</p>\n<table>\n<thead>\n<tr>\n<th>生態演替的特徵</th>\n<th>引自棒形圖中的證據</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>物種組成的改變</td>\n<td>＿＿＿</td>\n</tr>\n<tr>\n<td>物種多樣性的改變</td>\n<td>＿＿＿</td>\n</tr>\n</tbody>\n</table>",
   "file": "2023_P1_QU(CHI).md"
