   "text": "下圖顯示草莓的外觀及其垂直切面。草莓表面的瘦果是其果實：\n\n![圖](2023_P1_crops/b9.png)\n\n(a) 以下是一項關於瘦果在草莓發育時的角色的探究：\n\n| 處理方法 | 草莓的相對大小和外型 |\n| --- | --- |\n| | 第 1 天 | 第 20 天 |\n| 1. 瘦果完整無缺 | （圖） | （圖） |\n| 2. 在第 1 天去除所有瘦果 | （圖） | （圖） |\n| 3. 在第 1 天去除所有瘦果，然後定期噴灑生長素 | （圖） | （圖） |\n\n(b) (i) 寫出比較以下處理方法的結果而得到的推論，以完成下表：（3 分）\n\n| 處理方法 | 推論 |\n|---|---|\n| 比較 1 和 2 | ＿＿＿ |\n| 比較 2 和 3 | ＿＿＿ |\n| 比較 1 和 3 | ＿＿＿ |\n\n(ii) 根據結果，提出導致草莓增大的一項假說。（1 分）\n\n(iii) 細閱以下另一個處理方法：\n\n| 處理方法 | 草莓的相對大小和外型 |\n| --- | --- |\n| 4. 在第 1 天去除位於草莓下半部的瘦果，保留上半部的瘦果 | （圖） |\n\n就實驗設計而言，與處理方法 1 和 2 比較，處理方法 4 有什麼優點？（1 分）\n\n(c) 舉出一個由生長素誘發的生長反應的例子，並指出牠對植物的重要性。（2 分）",
   "html": "<p>下圖顯示草莓的外觀及其垂直切面。草莓表面的瘦果是其果實：</p>\n<p><img alt=\"圖\" src=\"bio_2023_P1_crops/b9.png\" /></p>\n<p>(a) 以下是一項關於瘦果在草莓發育時的角色的探究：</p>\n<table>\n<thead>\n<tr>\n<th>處理方法</th>\n<th>草莓的相對大小和外型</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td></td>\n<td>第 1 天</td>\n</tr>\n<tr>\n<td>1. 瘦果完整無缺</td>\n<td>（圖）</td>\n</tr>\n<tr>\n<td>2. 在第 1 天去除所有瘦果</td>\n<td>（圖）</td>\n</tr>\n<tr>\n<td>3. 在第 1 天去除所有瘦果，然後定期噴灑生長素</td>\n<td>（圖）</td>\n</tr>\n</tbody>\n</table>\n<p>(b) (i) 寫出比較以下處理方法的結果而得到的推論，以完成下表：（3 分）</p>\n<table>\n<thead>\n<tr>\n<th>處理方法</th>\n<th>推論</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>比較 1 和 2</td>\n<td>＿＿＿</td>\n</tr>\n<tr>\n<td>比較 2 和 3</td>\n<td>＿＿＿</td>\n</tr>\n<tr>\n<td>比較 1 和 3</td>\n<td>＿＿＿</td>\n</tr>\n</tbody>\n</table>\n<p>(ii) 根據結果，提出導致草莓增大的一項假說。（1 分）</p>\n<p>(iii) 細閱以下另一個處理方法：</p>\n<table>\n<thead>\n<tr>\n<th>處理方法</th>\n<th>草莓的相對大小和外型</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>4. 在第 1 天去除位於草莓下半部的瘦果，保留上半部的瘦果</td>\n<td>（圖）</td>\n</tr>\n</tbody>\n</table>\n<p>就實驗設計而言，與處理方法 1 和 2 比較，處理方法 4 有什麼優點？（1 分）</p>\n<p>(c) 舉出一個由生長素誘發的生長反應的例子，並指出牠對植物的重要性。（2 分）</p>",
