   "text": "下圖顯示三個植物物種（X、Y 和 Z）在光強度改變時，其光合作用速率隨光強度的變化。該三個植物物種均在同一生境內。\n\n![圖](2023_P1_crops/q10.png)\n\n由上圖可以得出以下哪項推斷？\n\n- A. 三個物種中，物種 Y 生長得最高\n- B. 在陰暗情況下，物種 Z 最具競爭力\n- C. 在所有光照情況下，物種 Y 較物種 X 優勝\n- D. 移除物種 Z 會增加物種 X 的光合作用速率",
   "html": "<p>下圖顯示三個植物物種（X、Y 和 Z）在光強度改變時，其光合作用速率隨光強度的變化。該三個植物物種均在同一生境內。</p>\n<p><img alt=\"圖\" src=\"bio_2023_P1_crops/q10.png\" /></p>\n<p>由上圖可以得出以下哪項推斷？</p>\n<ul>\n<li>A. 三個物種中，物種 Y 生長得最高</li>\n<li>B. 在陰暗情況下，物種 Z 最具競爭力</li>\n<li>C. 在所有光照情況下，物種 Y 較物種 X 優勝</li>\n<li>D. 移除物種 Z 會增加物種 X 的光合作用速率</li>\n</ul>",
