   "html": "<p>以下哪些過程產生 ATP？</p>\n<p>(1) 糖酵解\n(2) 卡爾文循環\n(3) 光化學反應</p>\n<ul>\n<li>A. 只有 (1) 和 (2)</li>\n<li>B. 只有 (1) 和 (3)</li>\n<li>C. 只有 (2) 和 (3)</li>\n<li>D. (1)、(2) 和 (3)</li>\n</ul>",
