   "text": "參考以下顯微照相，解答第 12 至 14 題。照片顯示某個植物部位的橫切面在不同放大倍數下的影像：\n\n![圖](2023_P1_crops/q12_14a.png)\n\n![圖](2023_P1_crops/q12_14b.png)\n\n哪個組合正確配對該切片是取自植物的哪個部位和顯微照片呈現的支持證據？\n\n- A. 根部：表皮上有毛\n- B. 根部：中央具有薄壁細胞\n- C. 莖部：表皮上有角質層\n- D. 莖部：周邊具有維管束",
