   "text": "（參考第 15 題的探究。）\n\n步驟 6 量度因變量。以下哪項可以用來量度這探究的因變量？\n\n(1) 蛋白立方體消失所需的時間\n(2) 在固定時間內，蛋白立方體形狀的改變\n(3) 在固定時間內，蛋白立方體重量的改變\n\n- A. 只有 (1) 和 (2)\n- B. 只有 (1) 和 (3)\n- C. 只有 (2) 和 (3)\n- D. (1)、(2) 和 (3)",
   "html": "<p>（參考第 15 題的探究。）</p>\n<p>步驟 6 量度因變量。以下哪項可以用來量度這探究的因變量？</p>\n<p>(1) 蛋白立方體消失所需的時間\n(2) 在固定時間內，蛋白立方體形狀的改變\n(3) 在固定時間內，蛋白立方體重量的改變</p>\n<ul>\n<li>A. 只有 (1) 和 (2)</li>\n<li>B. 只有 (1) 和 (3)</li>\n<li>C. 只有 (2) 和 (3)</li>\n<li>D. (1)、(2) 和 (3)</li>\n</ul>",
