   "text": "參考以下有關黃蜂 P、毛蟲 Q 和病毒 R 之間的關係，解答第 22 和 23 題：\n\n![圖](2023_P1_crops/q22_23.png)\n\n黃蜂 P 會在毛蟲 Q 體內產卵；當卵孵化後，黃蜂幼蟲會進食毛蟲的身體組織，最後把牠們殺死。\n\n近期研究顯示，這些黃蜂是病毒 R 的宿主，病毒 DNA 會成為黃蜂基因組的一部分，並傳給黃蜂的後代。黃蜂注射卵入毛蟲體內時，會同時釋放病毒 R，病毒 R 會抑制毛蟲的身體防禦機制，保護黃蜂的卵。\n\n以下哪項正確描述牠們的攝食角色？\n\n- A. 病毒是最高消費者\n- B. 毛蟲是生產者\n- C. 黃蜂成蟲是初級消費者\n- D. 黃蜂幼蟲是次級消費者",
   "html": "<p>參考以下有關黃蜂 P、毛蟲 Q 和病毒 R 之間的關係，解答第 22 和 23 題：</p>\n<p><img alt=\"圖\" src=\"bio_2023_P1_crops/q22_23.png\" /></p>\n<p>黃蜂 P 會在毛蟲 Q 體內產卵；當卵孵化後，黃蜂幼蟲會進食毛蟲的身體組織，最後把牠們殺死。</p>\n<p>近期研究顯示，這些黃蜂是病毒 R 的宿主，病毒 DNA 會成為黃蜂基因組的一部分，並傳給黃蜂的後代。黃蜂注射卵入毛蟲體內時，會同時釋放病毒 R，病毒 R 會抑制毛蟲的身體防禦機制，保護黃蜂的卵。</p>\n<p>以下哪項正確描述牠們的攝食角色？</p>\n<ul>\n<li>A. 病毒是最高消費者</li>\n<li>B. 毛蟲是生產者</li>\n<li>C. 黃蜂成蟲是初級消費者</li>\n<li>D. 黃蜂幼蟲是次級消費者</li>\n</ul>",
