   "text": "參考以下有關五個細菌物種的親緣關係，解答第 29 和 30 題。酶 X 見於大部分細菌。下表顯示五個細菌物種（J、K、L、M 和 N）編碼着酶 X 的基因，其核苷酸差異的數目：\n\n![圖](2023_P1_crops/q29_30.png)\n\n按物種的親緣關係排序，由最接近 L 至最遠離 L 的正確次序是：\n\n- A. L、J、K、N、M\n- B. L、J、M、N、K\n- C. L、M、N、K、J\n- D. L、N、M、K、J",
   "html": "<p>參考以下有關五個細菌物種的親緣關係，解答第 29 和 30 題。酶 X 見於大部分細菌。下表顯示五個細菌物種（J、K、L、M 和 N）編碼着酶 X 的基因，其核苷酸差異的數目：</p>\n<p><img alt=\"圖\" src=\"bio_2023_P1_crops/q29_30.png\" /></p>\n<p>按物種的親緣關係排序，由最接近 L 至最遠離 L 的正確次序是：</p>\n<ul>\n<li>A. L、J、K、N、M</li>\n<li>B. L、J、M、N、K</li>\n<li>C. L、M、N、K、J</li>\n<li>D. L、N、M、K、J</li>\n</ul>",
