   "text": "（參考第 29 題的表。）\n\n五個物種的編碼酶 X 基因的核苷酸有所不同，但五個物種的酶 X 仍具相同功能。以下哪項是這個現象的可能解釋？\n\n(1) 所形成的多肽長度相同\n(2) [?]\n(3) [?]\n\n- A. 只有 (1) 和 (2)\n- B. 只有 (1) 和 (3)\n- C. 只有 (2) 和 (3)\n- D. (1)、(2) 和 (3)",
   "html": "<p>（參考第 29 題的表。）</p>\n<p>五個物種的編碼酶 X 基因的核苷酸有所不同，但五個物種的酶 X 仍具相同功能。以下哪項是這個現象的可能解釋？</p>\n<p>(1) 所形成的多肽長度相同\n(2) [?]\n(3) [?]</p>\n<ul>\n<li>A. 只有 (1) 和 (2)</li>\n<li>B. 只有 (1) 和 (3)</li>\n<li>C. 只有 (2) 和 (3)</li>\n<li>D. (1)、(2) 和 (3)</li>\n</ul>",
