   "text": "（參考第 32 題的圖。）\n\n患者的血液葡萄糖水平最終會下降，這是因為：\n\n(1) 胰高血糖素的作用\n(2) 體細胞的呼吸作用\n(3) 葡萄糖會經尿液流失\n\n- A. 只有 (3)\n- B. 只有 (1) 和 (2)\n- C. 只有 (2) 和 (3)\n- D. (1)、(2) 和 (3)",
   "html": "<p>（參考第 32 題的圖。）</p>\n<p>患者的血液葡萄糖水平最終會下降，這是因為：</p>\n<p>(1) 胰高血糖素的作用\n(2) 體細胞的呼吸作用\n(3) 葡萄糖會經尿液流失</p>\n<ul>\n<li>A. 只有 (3)</li>\n<li>B. 只有 (1) 和 (2)</li>\n<li>C. 只有 (2) 和 (3)</li>\n<li>D. (1)、(2) 和 (3)</li>\n</ul>",
