   "text": "（參考第 34 題的圖。）\n\n以下哪個組合正確比較構造 Y 內的血管？\n\n- A. Y 內的靜脈：有較小的管腔；Y 內的動脈：有較大的管腔\n- B. Y 內的靜脈：運帶含氧血；Y 內的動脈：運帶缺氧血\n- C. Y 內的靜脈：其血液含較多葡萄糖；Y 內的動脈：其血液含較少葡萄糖\n- D. Y 內的靜脈：血液流往胎盤；Y 內的動脈：血液流往胎兒心臟",
   "html": "<p>（參考第 34 題的圖。）</p>\n<p>以下哪個組合正確比較構造 Y 內的血管？</p>\n<ul>\n<li>A. Y 內的靜脈：有較小的管腔；Y 內的動脈：有較大的管腔</li>\n<li>B. Y 內的靜脈：運帶含氧血；Y 內的動脈：運帶缺氧血</li>\n<li>C. Y 內的靜脈：其血液含較多葡萄糖；Y 內的動脈：其血液含較少葡萄糖</li>\n<li>D. Y 內的靜脈：血液流往胎盤；Y 內的動脈：血液流往胎兒心臟</li>\n</ul>",
