   "text": "某人成功接種對抗傳染病 P 的疫苗。以下哪圖正確顯示當這人受傳染病 P 的病原體入侵時，其抗體水平的變化？\n\n- A.\n\n![圖](2023_P1_crops/q36_a.png)\n\n- B.\n\n![圖](2023_P1_crops/q36_b.png)\n\n- C.\n\n![圖](2023_P1_crops/q36_c.png)\n\n- D.\n\n![圖](2023_P1_crops/q36_d.png)",
   "html": "<p>某人成功接種對抗傳染病 P 的疫苗。以下哪圖正確顯示當這人受傳染病 P 的病原體入侵時，其抗體水平的變化？</p>\n<ul>\n<li>A.</li>\n</ul>\n<p><img alt=\"圖\" src=\"bio_2023_P1_crops/q36_a.png\" /></p>\n<ul>\n<li>B.</li>\n</ul>\n<p><img alt=\"圖\" src=\"bio_2023_P1_crops/q36_b.png\" /></p>\n<ul>\n<li>C.</li>\n</ul>\n<p><img alt=\"圖\" src=\"bio_2023_P1_crops/q36_c.png\" /></p>\n<ul>\n<li>D.</li>\n</ul>\n<p><img alt=\"圖\" src=\"bio_2023_P1_crops/q36_d.png\" /></p>",
