   "text": "**(a)** 食品加工的過程中，若食物處理不當，就會受微生物污染。以下照片顯示兩種肉類產品：碎牛肉和牛扒：\n\n![圖](2023_P2_crops/q3a.png)\n\n(i) 提出為什麼碎牛肉較牛扒容易受微生物污染。（2 分）\n\n(ii) 為評估碎牛肉的安全和質素，將四個碎牛肉樣本進行微生物分析。將樣本分別用兩個不同溫度（5℃ 和 20℃）進行培養，每隔一段時間，就用平板培養法分別數算樣本的細菌 X 和細菌 Y 的菌落數目。記錄菌落數目增加 10 倍所需的時間。結果如下表所示：\n\n![圖](2023_P2_crops/q3a_table.png)\n\n（表：菌落數目增加 10 倍所需的時間，單位為小時，按樣本、細菌 X／Y 及 5℃／20℃ 分類。）\n\n(1) 計算在 5℃ 和 20℃ 時，細菌 X 和細菌 Y 的菌落數目增加 10 倍所需的平均時間。按照以下格式在答題簿內以表列形式回答：（2 分）\n\n| | 細菌 X（5℃） | 細菌 X（20℃） | 細菌 Y（5℃） | 細菌 Y（20℃） |\n|---|---|---|---|---|\n| 平均時間（小時） | ＿＿＿ | ＿＿＿ | ＿＿＿ | ＿＿＿ |\n\n(2) 比較細菌 X 和細菌 Y 在不同溫度的生長速率。（2 分）\n\n(3) 根據 (2) 的答案，哪種細菌較有可能引致貯藏在雪櫃的食物樣本腐壞？試加以解釋。（3 分）\n\n(4) 細菌 Y 常見於動物的腸道。解釋為什麼細菌 Y 通常會用作肉類在食品加工過程中受微生物污染的指標。（2 分）\n\n---\n\n**(b)** (i) 透過用光學密度量度細菌培養物的混濁度，對細菌的生長進行監測。結果如下圖 I 所示：\n\n![圖](2023_P2_crops/q3b_growth.png)\n\n(1) 細菌生長的靜止期有什麼特徵？（2 分）\n\n(2) 參考量度光學密度的原理，由圖中找出證據以解釋為什麼靜止期是 CD 而不是 DE。（3 分）\n\n(3) 參考量度光學密度的原理，解釋為什麼在量度光學密度之前，需要將細菌培養物搖勻。（2 分）\n\n(ii) Pseudomonas aeruginosa 是對多種抗生素具抗性的細菌物種，牠導致免疫系統薄弱的住院病人出現嚴重感染。為評估不同抗生素對治療受 P. aeruginosa 感染的病人的效用，從病人取得 P. aeruginosa 以製備細菌培養物。將定量的細菌培養物加入盛有相同體積但不同濃度抗生素的小孔，如圖 II 所示。然後進行培養，培養後的結果如圖 III 所示：\n\n![圖](2023_P2_crops/q3b_plate.png)\n\n(1) 將抗生素對 P. aeruginosa 感染患者的療效按升序排列。（1 分）\n\n(2) 要有效治療患者，抗生素 S 的最低濃度是什麼？（1 分）",
   "html": "<p><strong>(a)</strong> 食品加工的過程中，若食物處理不當，就會受微生物污染。以下照片顯示兩種肉類產品：碎牛肉和牛扒：</p>\n<p><img alt=\"圖\" src=\"bio_2023_P2_crops/q3a.png\" /></p>\n<p>(i) 提出為什麼碎牛肉較牛扒容易受微生物污染。（2 分）</p>\n<p>(ii) 為評估碎牛肉的安全和質素，將四個碎牛肉樣本進行微生物分析。將樣本分別用兩個不同溫度（5℃ 和 20℃）進行培養，每隔一段時間，就用平板培養法分別數算樣本的細菌 X 和細菌 Y 的菌落數目。記錄菌落數目增加 10 倍所需的時間。結果如下表所示：</p>\n<p><img alt=\"圖\" src=\"bio_2023_P2_crops/q3a_table.png\" /></p>\n<p>（表：菌落數目增加 10 倍所需的時間，單位為小時，按樣本、細菌 X／Y 及 5℃／20℃ 分類。）</p>\n<p>(1) 計算在 5℃ 和 20℃ 時，細菌 X 和細菌 Y 的菌落數目增加 10 倍所需的平均時間。按照以下格式在答題簿內以表列形式回答：（2 分）</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>細菌 X（5℃）</th>\n<th>細菌 X（20℃）</th>\n<th>細菌 Y（5℃）</th>\n<th>細菌 Y（20℃）</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>平均時間（小時）</td>\n<td>＿＿＿</td>\n<td>＿＿＿</td>\n<td>＿＿＿</td>\n<td>＿＿＿</td>\n</tr>\n</tbody>\n</table>\n<p>(2) 比較細菌 X 和細菌 Y 在不同溫度的生長速率。（2 分）</p>\n<p>(3) 根據 (2) 的答案，哪種細菌較有可能引致貯藏在雪櫃的食物樣本腐壞？試加以解釋。（3 分）</p>\n<p>(4) 細菌 Y 常見於動物的腸道。解釋為什麼細菌 Y 通常會用作肉類在食品加工過程中受微生物污染的指標。（2 分）</p>\n<hr />\n<p><strong>(b)</strong> (i) 透過用光學密度量度細菌培養物的混濁度，對細菌的生長進行監測。結果如下圖 I 所示：</p>\n<p><img alt=\"圖\" src=\"bio_2023_P2_crops/q3b_growth.png\" /></p>\n<p>(1) 細菌生長的靜止期有什麼特徵？（2 分）</p>\n<p>(2) 參考量度光學密度的原理，由圖中找出證據以解釋為什麼靜止期是 CD 而不是 DE。（3 分）</p>\n<p>(3) 參考量度光學密度的原理，解釋為什麼在量度光學密度之前，需要將細菌培養物搖勻。（2 分）</p>\n<p>(ii) Pseudomonas aeruginosa 是對多種抗生素具抗性的細菌物種，牠導致免疫系統薄弱的住院病人出現嚴重感染。為評估不同抗生素對治療受 P. aeruginosa 感染的病人的效用，從病人取得 P. aeruginosa 以製備細菌培養物。將定量的細菌培養物加入盛有相同體積但不同濃度抗生素的小孔，如圖 II 所示。然後進行培養，培養後的結果如圖 III 所示：</p>\n<p><img alt=\"圖\" src=\"bio_2023_P2_crops/q3b_plate.png\" /></p>\n<p>(1) 將抗生素對 P. aeruginosa 感染患者的療效按升序排列。（1 分）</p>\n<p>(2) 要有效治療患者，抗生素 S 的最低濃度是什麼？（1 分）</p>",
