   "text": "質量相同的物質 P 和 Q 於溫度 $T_1$ 時均為固體。下面的線圖顯示物質的溫度與能量傳遞的變化。\n\n![溫度—能量傳遞線圖](2024_P1_crops/q01.png)\n\n以下哪項敘述正確？\n\n- A. P 比 Q 有較高的熔點。\n- B. P 的熔解比潛熱較 Q 小。\n- C. 固體 P 的比熱容較固體 Q 大。\n- D. 於溫度 $T_2$，P 是氣體而 Q 為固體。",
   "html": "<p>質量相同的物質 P 和 Q 於溫度 $T_1$ 時均為固體。下面的線圖顯示物質的溫度與能量傳遞的變化。</p>\n<p><img alt=\"溫度—能量傳遞線圖\" src=\"phys_2024_P1_crops/q01.png\" /></p>\n<p>以下哪項敘述正確？</p>\n<ul>\n<li>A. P 比 Q 有較高的熔點。</li>\n<li>B. P 的熔解比潛熱較 Q 小。</li>\n<li>C. 固體 P 的比熱容較固體 Q 大。</li>\n<li>D. 於溫度 $T_2$，P 是氣體而 Q 為固體。</li>\n</ul>",
