   "text": "從電冰箱取出一瓶溫度為 4 °C 的水並置於桌上。室溫為 30 °C。\n\n![圖 1.1 水瓶](2024_P1_crops/b01.png)\n\n(a)　指出熱從周圍環境傳遞至該瓶水的一個方式。（1 分）\n\n(b)　解釋以鋁箔包裹瓶子會否加快其溫度的上升率。（2 分）\n\n(c)　經一段時間後，有水滴在瓶子表面形成。\n\n　　(i)　指出水滴的來源。（1 分）\n\n　　(ii)　假設在瓶子表面收集到 0.40 g 的水滴，估算這些水滴所釋放的潛熱。已知：水的汽化比潛熱 = $2.26 \\times 10^{6}$ J kg⁻¹。（2 分）",
   "html": "<p>從電冰箱取出一瓶溫度為 4 °C 的水並置於桌上。室溫為 30 °C。</p>\n<p><img alt=\"圖 1.1 水瓶\" src=\"phys_2024_P1_crops/b01.png\" /></p>\n<p>(a)　指出熱從周圍環境傳遞至該瓶水的一個方式。（1 分）</p>\n<p>(b)　解釋以鋁箔包裹瓶子會否加快其溫度的上升率。（2 分）</p>\n<p>(c)　經一段時間後，有水滴在瓶子表面形成。</p>\n<p>(i)　指出水滴的來源。（1 分）</p>\n<p>(ii)　假設在瓶子表面收集到 0.40 g 的水滴，估算這些水滴所釋放的潛熱。已知：水的汽化比潛熱 = $2.26 \\times 10^{6}$ J kg⁻¹。（2 分）</p>",
