   "text": "如果把 0.5 kg 於 50 °C 的水與 2.0 kg 於 0 °C 的冰混合，混合物的最終溫度是多少？\n\n已知：水的比熱容 = 4200 J kg⁻¹ °C⁻¹　冰的熔解比潛熱 = $3.34 \\times 10^{5}$ J kg⁻¹\n\n- A. −5 °C [?]\n- B. 0 °C\n- C. 10 °C\n- D. 25 °C",
