   "text": "圖 2.1 顯示一固定體積的密閉容器，載有氬（一單原子氣體）並維持於溫度 $T$。容器內氬原子的方均根速率 ($c_{r.m.s.}$) 為 500 m s⁻¹。\n\n![圖 2.1 密閉容器](2024_P1_crops/b02.png)\n\n(a)　(i)　計算氬原子的平均動能 $E_k$。已知一氬原子的質量為 $6.63 \\times 10^{-26}$ kg。（2 分）\n\n　　(ii)　據此或以其他方法，求 $T$（以 K 表達）。（2 分）\n\n(b)　如果容器洩漏了一些氬而溫度則維持在 $T$，指出容器內氬原子的方均根速率或有的改變，並作解釋。（2 分）",
   "html": "<p>圖 2.1 顯示一固定體積的密閉容器，載有氬（一單原子氣體）並維持於溫度 $T$。容器內氬原子的方均根速率 ($c_{r.m.s.}$) 為 500 m s⁻¹。</p>\n<p><img alt=\"圖 2.1 密閉容器\" src=\"phys_2024_P1_crops/b02.png\" /></p>\n<p>(a)　(i)　計算氬原子的平均動能 $E_k$。已知一氬原子的質量為 $6.63 \\times 10^{-26}$ kg。（2 分）</p>\n<p>(ii)　據此或以其他方法，求 $T$（以 K 表達）。（2 分）</p>\n<p>(b)　如果容器洩漏了一些氬而溫度則維持在 $T$，指出容器內氬原子的方均根速率或有的改變，並作解釋。（2 分）</p>",
