   "text": "一質量為 0.20 kg 的小方塊 P 靜置於水平桌子的 A 邊，如圖所示。桌面從 A 到 B 為光滑，而從 B 到 C 則是粗糙的。空氣阻力可忽略不計。\n\n![圖 3.1 小方塊於桌面上](2024_P1_crops/b03.png)\n\n一 0.30 N 的水平力作用於方塊。\n\n(a)　當方塊行進了 0.75 m 至 B 點，求它的速率。（2 分）\n\n(b)　在方塊 P 剛到達 B 時將該水平力移除。當方塊從 B 續往 C 前行，在下面的隔離體圖上標示方塊所受的力（一個或多個）並寫出其名稱。（2 分）\n\n(c)　方塊離開桌子的 C 邊，於 0.35 s 後到達地面上的 K 點。估算桌子的高度。（2 分）",
   "html": "<p>一質量為 0.20 kg 的小方塊 P 靜置於水平桌子的 A 邊，如圖所示。桌面從 A 到 B 為光滑，而從 B 到 C 則是粗糙的。空氣阻力可忽略不計。</p>\n<p><img alt=\"圖 3.1 小方塊於桌面上\" src=\"phys_2024_P1_crops/b03.png\" /></p>\n<p>一 0.30 N 的水平力作用於方塊。</p>\n<p>(a)　當方塊行進了 0.75 m 至 B 點，求它的速率。（2 分）</p>\n<p>(b)　在方塊 P 剛到達 B 時將該水平力移除。當方塊從 B 續往 C 前行，在下面的隔離體圖上標示方塊所受的力（一個或多個）並寫出其名稱。（2 分）</p>\n<p>(c)　方塊離開桌子的 C 邊，於 0.35 s 後到達地面上的 K 點。估算桌子的高度。（2 分）</p>",
