   "text": "質量為 $m$ 的方塊以恆定速度沿固定的粗糙斜面滑下，如圖所示。斜面與水平的夾角為 $\\theta$。\n\n![方塊沿斜面滑下](2024_P1_crops/q05.png)\n\n方塊作用於斜面的力的量值是多少？\n\n- A. $mg$\n- B. $mg\\sin\\theta$\n- C. $mg\\cos\\theta$\n- D. [?]",
   "html": "<p>質量為 $m$ 的方塊以恆定速度沿固定的粗糙斜面滑下，如圖所示。斜面與水平的夾角為 $\\theta$。</p>\n<p><img alt=\"方塊沿斜面滑下\" src=\"phys_2024_P1_crops/q05.png\" /></p>\n<p>方塊作用於斜面的力的量值是多少？</p>\n<ul>\n<li>A. $mg$</li>\n<li>B. $mg\\sin\\theta$</li>\n<li>C. $mg\\cos\\theta$</li>\n<li>D. [?]</li>\n</ul>",
