   "text": "圖 5.1 代表揚聲器所產生的聲波中，空氣粒子於某一瞬間的分布。\n\n![圖 5.1 空氣粒子分布](2024_P1_crops/b05.png)\n\n(a)　在所提供的網格，草繪該瞬間空氣粒子的位移-距離線圖，取向右的位移為正 (+)。（2 分）\n\n(b)　在圖示的瞬間，指出一個區域（P、Q、R、S 或 T）其中的\n\n　　(i)　空氣粒子運動速率最大；（1 分）\n\n　　(ii)　空氣壓強最低。（1 分）",
   "html": "<p>圖 5.1 代表揚聲器所產生的聲波中，空氣粒子於某一瞬間的分布。</p>\n<p><img alt=\"圖 5.1 空氣粒子分布\" src=\"phys_2024_P1_crops/b05.png\" /></p>\n<p>(a)　在所提供的網格，草繪該瞬間空氣粒子的位移-距離線圖，取向右的位移為正 (+)。（2 分）</p>\n<p>(b)　在圖示的瞬間，指出一個區域（P、Q、R、S 或 T）其中的</p>\n<p>(i)　空氣粒子運動速率最大；（1 分）</p>\n<p>(ii)　空氣壓強最低。（1 分）</p>",
