   "text": "以下線圖顯示於不同空氣溫度下聲音的速率。\n\n![圖 7.1 聲速—溫度線圖](2024_P1_crops/b07a.png)\n\n(a)　根據線圖，指出聲音的速率和空氣溫度的關係。（1 分）\n\n(b)　圖 7.2 顯示於晚間地面轉涼，來自鐘樓的聲音從遠處到達觀察者。\n\n![圖 7.2 晚間聲音折射](2024_P1_crops/b07b.png)\n\n可怎樣以地面上空氣層之間的溫差來解釋圖 7.2 的情況？（2 分）\n\n(c)　已知空氣溫度為 10 °C。根據圖 7.1 的線圖：\n\n　　(i)　估算光速與聲速之比。（1 分）\n\n　　(ii)　如果在雷暴中，一觀察者 O 於看見閃電 3.0 s 後才聽到雷響，估算雷暴距離 O 有多遠。（2 分）",
   "html": "<p>以下線圖顯示於不同空氣溫度下聲音的速率。</p>\n<p><img alt=\"圖 7.1 聲速—溫度線圖\" src=\"phys_2024_P1_crops/b07a.png\" /></p>\n<p>(a)　根據線圖，指出聲音的速率和空氣溫度的關係。（1 分）</p>\n<p>(b)　圖 7.2 顯示於晚間地面轉涼，來自鐘樓的聲音從遠處到達觀察者。</p>\n<p><img alt=\"圖 7.2 晚間聲音折射\" src=\"phys_2024_P1_crops/b07b.png\" /></p>\n<p>可怎樣以地面上空氣層之間的溫差來解釋圖 7.2 的情況？（2 分）</p>\n<p>(c)　已知空氣溫度為 10 °C。根據圖 7.1 的線圖：</p>\n<p>(i)　估算光速與聲速之比。（1 分）</p>\n<p>(ii)　如果在雷暴中，一觀察者 O 於看見閃電 3.0 s 後才聽到雷響，估算雷暴距離 O 有多遠。（2 分）</p>",
   "file": "2024_P1_QU(CHI).md"
