   "text": "如圖所示，質量分別為 3.0 kg 和 1.0 kg 的方塊 X 和 Y，以一條不能伸長的輕繩連接着，而繩穿過固定於天花板的光滑輕滑輪。從靜止釋放該兩方塊。\n\n![滑輪系統](2024_P1_crops/q08.png)\n\n求方塊 X 到達地面所需的時間。空氣阻力可忽略不計。\n\n- A. 0.55 s\n- B. 0.64 s [?]\n- C. 0.65 s [?]\n- D. 0.78 s [?]",
   "html": "<p>如圖所示，質量分別為 3.0 kg 和 1.0 kg 的方塊 X 和 Y，以一條不能伸長的輕繩連接着，而繩穿過固定於天花板的光滑輕滑輪。從靜止釋放該兩方塊。</p>\n<p><img alt=\"滑輪系統\" src=\"phys_2024_P1_crops/q08.png\" /></p>\n<p>求方塊 X 到達地面所需的時間。空氣阻力可忽略不計。</p>\n<ul>\n<li>A. 0.55 s</li>\n<li>B. 0.64 s [?]</li>\n<li>C. 0.65 s [?]</li>\n<li>D. 0.78 s [?]</li>\n</ul>",
