   "text": "圖 8.1 顯示一鉛筆置於一杯水中，觀察者沿豎直向下望。已知水的折射率為 1.33。\n\n![圖 8.1 鉛筆置於水中](2024_P1_crops/b08.png)\n\n光線 P 和 Q 來自鉛筆的尖端 O，其中 Q 沿豎直方向。\n\n(a)　在圖 8.1 完成這些光線的路徑，並標示觀察者所看到 O 的像（將其標註為 I）。（2 分）\n\n(b)　光線 P 和光線 Q 的夾角為 1.5°。求光線 P 的折射角。（2 分）\n\n(c)　據此或以其他方法，如果水深為 0.10 m，求像 I 與水面的距離。（2 分）",
   "html": "<p>圖 8.1 顯示一鉛筆置於一杯水中，觀察者沿豎直向下望。已知水的折射率為 1.33。</p>\n<p><img alt=\"圖 8.1 鉛筆置於水中\" src=\"phys_2024_P1_crops/b08.png\" /></p>\n<p>光線 P 和 Q 來自鉛筆的尖端 O，其中 Q 沿豎直方向。</p>\n<p>(a)　在圖 8.1 完成這些光線的路徑，並標示觀察者所看到 O 的像（將其標註為 I）。（2 分）</p>\n<p>(b)　光線 P 和光線 Q 的夾角為 1.5°。求光線 P 的折射角。（2 分）</p>\n<p>(c)　據此或以其他方法，如果水深為 0.10 m，求像 I 與水面的距離。（2 分）</p>",
   "file": "2024_P1_QU(CHI).md"
