   "text": "某人以為當他用足夠大的力拉自己的頭髮，最終可把自己拉起至離開地面。這說法為謬誤的理由是\n\n- A. 拉力是這人內在的作用力，但不是作用於這人的外力。\n- B. 不可能產生大於一個人重量的拉力。\n- C. 拉力會被這人的重量抵消。\n- D. 拉力不可能克服大氣壓強的力。",
   "html": "<p>某人以為當他用足夠大的力拉自己的頭髮，最終可把自己拉起至離開地面。這說法為謬誤的理由是</p>\n<ul>\n<li>A. 拉力是這人內在的作用力，但不是作用於這人的外力。</li>\n<li>B. 不可能產生大於一個人重量的拉力。</li>\n<li>C. 拉力會被這人的重量抵消。</li>\n<li>D. 拉力不可能克服大氣壓強的力。</li>\n</ul>",
