   "text": "在一桌球枱上，一質量 0.16 kg 的桌球以勻速率 1.20 m s⁻¹ 與邊墊作彈性碰撞，並以相同的速率從邊墊法向回彈，如圖所示。若碰撞時間為 0.003 s，求碰撞期間邊墊作用於桌球的平均力。\n\n![桌球與邊墊碰撞（頂視圖）](2024_P1_crops/q11.png)\n\n- A. 0 N\n- B. 64 N\n- C. 128 N\n- D. 256 N",
   "html": "<p>在一桌球枱上，一質量 0.16 kg 的桌球以勻速率 1.20 m s⁻¹ 與邊墊作彈性碰撞，並以相同的速率從邊墊法向回彈，如圖所示。若碰撞時間為 0.003 s，求碰撞期間邊墊作用於桌球的平均力。</p>\n<p><img alt=\"桌球與邊墊碰撞（頂視圖）\" src=\"phys_2024_P1_crops/q11.png\" /></p>\n<ul>\n<li>A. 0 N</li>\n<li>B. 64 N</li>\n<li>C. 128 N</li>\n<li>D. 256 N</li>\n</ul>",
