   "html": "<p>圖示一粒子正進行勻速圓周運動。以下哪項正確顯示粒子於圖示一刻的速度和加速度方向？</p>\n<p><img alt=\"粒子圓周運動之速度與加速度方向（選項 A–D）\" src=\"phys_2024_P1_crops/q12.png\" /></p>\n<ul>\n<li>A.</li>\n<li>B.</li>\n<li>C.</li>\n<li>D.</li>\n</ul>",
