   "text": "於半徑為 $r$ 的圓形軌道上，一衛星以週期 24 小時環繞地球運行。於半徑為 $2r$ 的圓形軌道上，另一繞地球運行的衛星其週期\n\n- A. 小於 24 小時\n- B. 為 24 小時\n- C. 介乎 24 小時至 48 小時\n- D. 大於 48 小時",
   "html": "<p>於半徑為 $r$ 的圓形軌道上，一衛星以週期 24 小時環繞地球運行。於半徑為 $2r$ 的圓形軌道上，另一繞地球運行的衛星其週期</p>\n<ul>\n<li>A. 小於 24 小時</li>\n<li>B. 為 24 小時</li>\n<li>C. 介乎 24 小時至 48 小時</li>\n<li>D. 大於 48 小時</li>\n</ul>",
