   "text": "氡 (Rn-222) 是一種無色、無臭、無味的放射性氣體。它從地下的基岩物料或含花崗岩的混凝土中釋出。Rn-222 的衰變會放出 α 粒子，而其半衰期為 3.82 日。\n\n(a)　(i)　求 Rn-222 的衰變常數（以 s⁻¹ 為單位）。（2 分）\n\n　　(ii)　於建築物內 1 m³ 的空氣中，氡所造成的平均放射強度約為 48 Bq。估算建築物內 1 m³ 空氣中氡原子數目的平均值。（2 分）\n\n　　(iii)　雖然 α 粒子的貫穿能力有限，但是為什麼室內的氡被視為對人體有害？（2 分）\n\n(b)　Rn-222 屬於從鈾-238 (U-238) 開始的衰變系。已知 U-238 依次進行 α-β-β-α 衰變，而成釷-230 (Th-230)。\n\n![U-238 至 Th-230 的衰變系](2024_P1_crops/b13.png)\n\n以箭矢完成以下從 U-238 到 Th-230 的衰變系。（2 分）\n\n---\n\n*試卷完 —*\n\n## 待人工核對\n\n本卷為第 2 層文字交貨，由 easyocr（ch_tra+en，GPU）掃描底稿清洗而成；現模型無影像輸入，未能對頁影像覆核。以下內容建議第 3 層精修時對頁核實：\n\n- 第 2 題：選項 A（OCR 讀作「−54°C」，疑為 −5 °C 或 5 °C）待對頁核實。\n- 第 5 題：選項 D（OCR 遺漏）待對頁補回；本稿以 [?] 標示。\n- 第 8 題：選項 B／C／D 之數值（0.55／0.64／0.65／0.78 s）OCR 底稿亂碼，待對頁核實。\n- 第 17 題：干涉結果表（X／P 相長或相消）OCR 底稿不全，待對頁核實。\n- 第 22 題：音調／響度比較表之「響度」一欄（OCR 讀作「黜」）待對頁核實。\n- 第 26 題：選項 B／C／D（磁力方向）OCR 底稿不全，僅錄得「指出紙面」「指入紙面」，待對頁補回。\n- 第 33 題：同位素表「放出的輻射」一欄（α／β／γ）OCR 底稿亂碼，待對頁核實。\n- 第 6 題（乙部）：紅色激光之波長（題幹缺）待對頁補回。\n- 第 11 題（乙部）：電橋公式及 $R_3$、$R_4$ 之已知值待對頁核實；$V_{out}$ 所跨端點待對頁補回。\n- 各圖：為 300dpi 原卷截圖（程式定位＋墨跡覆蓋率校驗；無視覺覆核，位置／範圍待 spot-check）；第 3 層再換成向量重繪。\n- 各小題分數以 OCR 辨識為準，待對頁核對。",
   "html": "<p>氡 (Rn-222) 是一種無色、無臭、無味的放射性氣體。它從地下的基岩物料或含花崗岩的混凝土中釋出。Rn-222 的衰變會放出 α 粒子，而其半衰期為 3.82 日。</p>\n<p>(a)　(i)　求 Rn-222 的衰變常數（以 s⁻¹ 為單位）。（2 分）</p>\n<p>(ii)　於建築物內 1 m³ 的空氣中，氡所造成的平均放射強度約為 48 Bq。估算建築物內 1 m³ 空氣中氡原子數目的平均值。（2 分）</p>\n<p>(iii)　雖然 α 粒子的貫穿能力有限，但是為什麼室內的氡被視為對人體有害？（2 分）</p>\n<p>(b)　Rn-222 屬於從鈾-238 (U-238) 開始的衰變系。已知 U-238 依次進行 α-β-β-α 衰變，而成釷-230 (Th-230)。</p>\n<p><img alt=\"U-238 至 Th-230 的衰變系\" src=\"phys_2024_P1_crops/b13.png\" /></p>\n<p>以箭矢完成以下從 U-238 到 Th-230 的衰變系。（2 分）</p>\n<hr />\n<p><em>試卷完 —</em></p>\n<h2>待人工核對</h2>\n<p>本卷為第 2 層文字交貨，由 easyocr（ch_tra+en，GPU）掃描底稿清洗而成；現模型無影像輸入，未能對頁影像覆核。以下內容建議第 3 層精修時對頁核實：</p>\n<ul>\n<li>第 2 題：選項 A（OCR 讀作「−54°C」，疑為 −5 °C 或 5 °C）待對頁核實。</li>\n<li>第 5 題：選項 D（OCR 遺漏）待對頁補回；本稿以 [?] 標示。</li>\n<li>第 8 題：選項 B／C／D 之數值（0.55／0.64／0.65／0.78 s）OCR 底稿亂碼，待對頁核實。</li>\n<li>第 17 題：干涉結果表（X／P 相長或相消）OCR 底稿不全，待對頁核實。</li>\n<li>第 22 題：音調／響度比較表之「響度」一欄（OCR 讀作「黜」）待對頁核實。</li>\n<li>第 26 題：選項 B／C／D（磁力方向）OCR 底稿不全，僅錄得「指出紙面」「指入紙面」，待對頁補回。</li>\n<li>第 33 題：同位素表「放出的輻射」一欄（α／β／γ）OCR 底稿亂碼，待對頁核實。</li>\n<li>第 6 題（乙部）：紅色激光之波長（題幹缺）待對頁補回。</li>\n<li>第 11 題（乙部）：電橋公式及 $R_3$、$R_4$ 之已知值待對頁核實；$V_{out}$ 所跨端點待對頁補回。</li>\n<li>各圖：為 300dpi 原卷截圖（程式定位＋墨跡覆蓋率校驗；無視覺覆核，位置／範圍待 spot-check）；第 3 層再換成向量重繪。</li>\n<li>各小題分數以 OCR 辨識為準，待對頁核對。</li>\n</ul>",
