   "text": "以單色光束 X 和 Y 組成的光束入射一玻璃方塊，並如圖所示分開成兩束。\n\n![光束 X、Y 入射玻璃方塊](2024_P1_crops/q14.png)\n\n以下有關光束 X 和 Y 的比較，哪項正確？\n\n(1)　X 有較高頻率。\n\n(2)　在玻璃中，X 有較高速率。\n\n(3)　在玻璃方塊中，X 的臨界角較大。\n\n- A. 只有 (1)\n- B. 只有 (3)\n- C. 只有 (1) 和 (2)\n- D. 只有 (2) 和 (3)",
   "html": "<p>以單色光束 X 和 Y 組成的光束入射一玻璃方塊，並如圖所示分開成兩束。</p>\n<p><img alt=\"光束 X、Y 入射玻璃方塊\" src=\"phys_2024_P1_crops/q14.png\" /></p>\n<p>以下有關光束 X 和 Y 的比較，哪項正確？</p>\n<p>(1)　X 有較高頻率。</p>\n<p>(2)　在玻璃中，X 有較高速率。</p>\n<p>(3)　在玻璃方塊中，X 的臨界角較大。</p>\n<ul>\n<li>A. 只有 (1)</li>\n<li>B. 只有 (3)</li>\n<li>C. 只有 (1) 和 (2)</li>\n<li>D. 只有 (2) 和 (3)</li>\n</ul>",
