   "text": "初始時，一列粒子均勻分布在一軟彈簧上。當一頻率為 10 Hz 的行波沿彈簧從左向右傳播，圖 (a) 和 (b) 顯示粒子於兩個時刻的位置。\n\n![彈簧上行波的粒子位置（圖 a、b）](2024_P1_crops/q16.png)\n\n以下哪項敘述正確？\n\n- A. 粒子 a 恆為靜止。\n- B. 粒子 b 和 c 以不同的振幅振動。\n- C. 這波的波長為 16 cm。\n- D. 要獲得這兩幅圖的最小時距為 0.05 s。",
   "html": "<p>初始時，一列粒子均勻分布在一軟彈簧上。當一頻率為 10 Hz 的行波沿彈簧從左向右傳播，圖 (a) 和 (b) 顯示粒子於兩個時刻的位置。</p>\n<p><img alt=\"彈簧上行波的粒子位置（圖 a、b）\" src=\"phys_2024_P1_crops/q16.png\" /></p>\n<p>以下哪項敘述正確？</p>\n<ul>\n<li>A. 粒子 a 恆為靜止。</li>\n<li>B. 粒子 b 和 c 以不同的振幅振動。</li>\n<li>C. 這波的波長為 16 cm。</li>\n<li>D. 要獲得這兩幅圖的最小時距為 0.05 s。</li>\n</ul>",
