   "text": "接駁至一訊號產生器的兩個相同揚聲器 $S_1$ 和 $S_2$ 產生反相的聲波，波長為 0.10 m。\n\n![揚聲器干涉裝置](2024_P1_crops/q17.png)\n\nOX 為 $S_1$ 和 $S_2$ 連線的垂直平分線。分別在 X 和 P 發生哪種干涉？\n\n| X | P |\n|---|---|\n| A. 相消 | 相長 [?] |\n| B. 相消 | 相消 [?] |\n| C. 相長 | 相消 [?] |\n| D. 相長 | 相長 [?] |",
