   "text": "一繩子有一端縛着振動器，另一端則固定於牆上。圖示振動器於某頻率時所形成的駐波。\n\n![駐波](2024_P1_crops/q18.png)\n\n當頻率增至兩倍，以下哪項敘述正確？\n\n- A. 波的振幅會增至兩倍。\n- B. 波長會增至兩倍。\n- C. 波的速率會增至兩倍。\n- D. 粒子 X 和 Y 會變為同相。",
