   "text": "電荷 $+Q$ 和 $-2Q$ 如圖示固定在 X 和 Y。\n\n![電荷 +Q、−2Q 及虛線](2024_P1_crops/q23.png)\n\n以下有關沿虛線上電場的描述，何者正確？\n\n(1)　在 X 和 Y 之間，這兩電荷各自所產生的電場方向相同。\n\n(2)　在 Y 的右方，合電場的方向總是向左。\n\n(3)　在虛線上存在着兩點，其合電場為零。\n\n- A. 只有 (2)\n- B. 只有 (3)\n- C. 只有 (1) 和 (2)\n- D. 只有 (1) 和 (3)",
   "html": "<p>電荷 $+Q$ 和 $-2Q$ 如圖示固定在 X 和 Y。</p>\n<p><img alt=\"電荷 +Q、−2Q 及虛線\" src=\"phys_2024_P1_crops/q23.png\" /></p>\n<p>以下有關沿虛線上電場的描述，何者正確？</p>\n<p>(1)　在 X 和 Y 之間，這兩電荷各自所產生的電場方向相同。</p>\n<p>(2)　在 Y 的右方，合電場的方向總是向左。</p>\n<p>(3)　在虛線上存在着兩點，其合電場為零。</p>\n<ul>\n<li>A. 只有 (2)</li>\n<li>B. 只有 (3)</li>\n<li>C. 只有 (1) 和 (2)</li>\n<li>D. 只有 (1) 和 (3)</li>\n</ul>",
