   "text": "圖 (1) 顯示一雙星系統，系統中兩恆星繞其質心 C 作勻速圓周運動。O 是處於兩恆星軌道同一平面的遙遠觀察者。\n\n![圖 (1) 雙星系統](2024_P2_crops/q1_5a.png)\n\n圖 (2) 顯示 O 量度來自兩恆星的某一譜線所得多普勒頻移 Δλ 跟時間的變化。線圖上時間 T 的瞬間對應圖 (1)。\n\n![圖 (2) 多普勒頻移曲線](2024_P2_crops/q1_5b.png)\n\n恆星 Y 於時間 T 向哪方運動？而哪一曲線，P 還是 Q，是屬於質量較大的恆星？\n\n| 恆星 Y 於時間 T 的運動方向 | 屬於質量較大恆星的曲線 |\n|---|---|\n| A. 趨向 O | Q |\n| B. 趨向 O | P |\n| C. 離開 O | Q |\n| D. 離開 O | P |",
   "html": "<p>圖 (1) 顯示一雙星系統，系統中兩恆星繞其質心 C 作勻速圓周運動。O 是處於兩恆星軌道同一平面的遙遠觀察者。</p>\n<p><img alt=\"圖 (1) 雙星系統\" src=\"phys_2024_P2_crops/q1_5a.png\" /></p>\n<p>圖 (2) 顯示 O 量度來自兩恆星的某一譜線所得多普勒頻移 Δλ 跟時間的變化。線圖上時間 T 的瞬間對應圖 (1)。</p>\n<p><img alt=\"圖 (2) 多普勒頻移曲線\" src=\"phys_2024_P2_crops/q1_5b.png\" /></p>\n<p>恆星 Y 於時間 T 向哪方運動？而哪一曲線，P 還是 Q，是屬於質量較大的恆星？</p>\n<table>\n<thead>\n<tr>\n<th>恆星 Y 於時間 T 的運動方向</th>\n<th>屬於質量較大恆星的曲線</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>A. 趨向 O</td>\n<td>Q</td>\n</tr>\n<tr>\n<td>B. 趨向 O</td>\n<td>P</td>\n</tr>\n<tr>\n<td>C. 離開 O</td>\n<td>Q</td>\n</tr>\n<tr>\n<td>D. 離開 O</td>\n<td>P</td>\n</tr>\n</tbody>\n</table>",
