   "text": "如果恆星 X 距離地球 20 pc，相隔 6 個月從地球觀察所得，相對於遙遠的恆星該恆星最大的角位移為多少？\n\n![視差圖](2024_P2_crops/q1_6.png)\n\n- A. 0.025 弧秒\n- B. 0.05 弧秒\n- C. 0.1 弧秒\n- D. 0.5 弧秒",
   "html": "<p>如果恆星 X 距離地球 20 pc，相隔 6 個月從地球觀察所得，相對於遙遠的恆星該恆星最大的角位移為多少？</p>\n<p><img alt=\"視差圖\" src=\"phys_2024_P2_crops/q1_6.png\" /></p>\n<ul>\n<li>A. 0.025 弧秒</li>\n<li>B. 0.05 弧秒</li>\n<li>C. 0.1 弧秒</li>\n<li>D. 0.5 弧秒</li>\n</ul>",
