   "text": "恆星 X 為主序星。它的半徑是太陽（光譜類型 G）的 8 倍，其光度為太陽的 250000 倍。恆星 X 屬哪一光譜類型？\n\n![赫羅圖（主序星）](2024_P2_crops/q1_8.png)\n\n- A. 類型 M\n- B. 類型 K\n- C. 類型 G\n- D. 類型 O",
   "html": "<p>恆星 X 為主序星。它的半徑是太陽（光譜類型 G）的 8 倍，其光度為太陽的 250000 倍。恆星 X 屬哪一光譜類型？</p>\n<p><img alt=\"赫羅圖（主序星）\" src=\"phys_2024_P2_crops/q1_8.png\" /></p>\n<ul>\n<li>A. 類型 M</li>\n<li>B. 類型 K</li>\n<li>C. 類型 G</li>\n<li>D. 類型 O</li>\n</ul>",
   "file": "2024_P2_QU(CHI).md"
