   "text": "圖示一原子的能級。能級間的電子躍遷會發射光子。\n\n![能級圖](2024_P2_crops/q2_3.png)\n\n下列哪項敍述正確？已知：在可見光譜中，光子的能量介乎 1.78 eV 和 3.10 eV\n\n(1)　這些光子有部分是在可見光譜內。\n\n(2)　所發射出的光子其頻率最多有兩種。\n\n(3)　波長最長的光子源自 −1 eV 和 −10 eV 之間的電子躍遷。\n\n- A. 只有 (1)\n- B. 只有 (2)\n- C. 只有 (1) 和 (3)\n- D. 只有 (2) 和 (3)",
   "html": "<p>圖示一原子的能級。能級間的電子躍遷會發射光子。</p>\n<p><img alt=\"能級圖\" src=\"phys_2024_P2_crops/q2_3.png\" /></p>\n<p>下列哪項敍述正確？已知：在可見光譜中，光子的能量介乎 1.78 eV 和 3.10 eV</p>\n<p>(1)　這些光子有部分是在可見光譜內。</p>\n<p>(2)　所發射出的光子其頻率最多有兩種。</p>\n<p>(3)　波長最長的光子源自 −1 eV 和 −10 eV 之間的電子躍遷。</p>\n<ul>\n<li>A. 只有 (1)</li>\n<li>B. 只有 (2)</li>\n<li>C. 只有 (1) 和 (3)</li>\n<li>D. 只有 (2) 和 (3)</li>\n</ul>",
