   "html": "<p>在一光電發射實驗中，就某一金屬的遏止電勢 $V_s$ 跟所用單色光強度 $I$ 的變化進行探究。哪一線圖代表實驗結果？</p>\n<p><img alt=\"遏止電勢 $V_s$ 對光強度 $I$ 線圖（選項 A–D）\" src=\"phys_2024_P2_crops/q2_4.png\" /></p>\n<ul>\n<li>A.</li>\n<li>B.</li>\n<li>C.</li>\n<li>D.</li>\n</ul>",
