   "text": "分別以波長 $\\lambda_1$ 和 $\\lambda_2$ 的單色光逐一照射金屬 X 和 Y，$\\lambda_1$ 可令兩金屬皆產生光電發射，而 $\\lambda_2$ 只能令金屬 Y 產生光電發射。以下哪項推斷正確？\n\n- A. $\\lambda_1 > \\lambda_2$　而 X 的臨閾頻率較高。\n- B. $\\lambda_1 > \\lambda_2$　而 Y 的臨閾頻率較高。\n- C. $\\lambda_1 < \\lambda_2$　而 X 的臨閾頻率較高。\n- D. $\\lambda_1 < \\lambda_2$　而 Y 的臨閾頻率較高。",
   "html": "<p>分別以波長 $\\lambda_1$ 和 $\\lambda_2$ 的單色光逐一照射金屬 X 和 Y，$\\lambda_1$ 可令兩金屬皆產生光電發射，而 $\\lambda_2$ 只能令金屬 Y 產生光電發射。以下哪項推斷正確？</p>\n<ul>\n<li>A. $\\lambda_1 &gt; \\lambda_2$　而 X 的臨閾頻率較高。</li>\n<li>B. $\\lambda_1 &gt; \\lambda_2$　而 Y 的臨閾頻率較高。</li>\n<li>C. $\\lambda_1 &lt; \\lambda_2$　而 X 的臨閾頻率較高。</li>\n<li>D. $\\lambda_1 &lt; \\lambda_2$　而 Y 的臨閾頻率較高。</li>\n</ul>",
   "file": "2024_P2_QU(CHI).md"
