   "text": "能量為 $E$ 的光子，其波長跟質量為 $m$ 的電子的德布羅意波長相等。以下哪一表達式跟電子的動量相等？（$c$ = 真空中的光速）\n\n(1)　$\\sqrt{2mE}$\n\n(2)　$mc$\n\n(3)　$\\dfrac{E}{c}$\n\n- A. 只有 (1)\n- B. 只有 (3)\n- C. 只有 (1) 和 (2)\n- D. 只有 (2) 和 (3)",
   "html": "<p>能量為 $E$ 的光子，其波長跟質量為 $m$ 的電子的德布羅意波長相等。以下哪一表達式跟電子的動量相等？（$c$ = 真空中的光速）</p>\n<p>(1)　$\\sqrt{2mE}$</p>\n<p>(2)　$mc$</p>\n<p>(3)　$\\dfrac{E}{c}$</p>\n<ul>\n<li>A. 只有 (1)</li>\n<li>B. 只有 (3)</li>\n<li>C. 只有 (1) 和 (2)</li>\n<li>D. 只有 (2) 和 (3)</li>\n</ul>",
