   "text": "在一透射電子顯微鏡 (TEM) 中，所發射出的電子以電子槍加速，然後通過下面方框圖中的元件 (1)–(3)，繼而經透鏡投影成像於屏上。\n\n![TEM 元件方框圖](2024_P2_crops/q2_7.png)\n\n下列哪一組合正確？\n\n| (1) | (2) | (3) |\n|---|---|---|\n| A. 會聚透鏡 | 物鏡 | 樣本 |\n| B. 會聚透鏡 | 樣本 | 物鏡 |\n| C. 物鏡 | 樣本 | 會聚透鏡 |\n| D. 樣本 | 會聚透鏡 | 物鏡 |",
   "html": "<p>在一透射電子顯微鏡 (TEM) 中，所發射出的電子以電子槍加速，然後通過下面方框圖中的元件 (1)–(3)，繼而經透鏡投影成像於屏上。</p>\n<p><img alt=\"TEM 元件方框圖\" src=\"phys_2024_P2_crops/q2_7.png\" /></p>\n<p>下列哪一組合正確？</p>\n<table>\n<thead>\n<tr>\n<th>(1)</th>\n<th>(2)</th>\n<th>(3)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>A. 會聚透鏡</td>\n<td>物鏡</td>\n<td>樣本</td>\n</tr>\n<tr>\n<td>B. 會聚透鏡</td>\n<td>樣本</td>\n<td>物鏡</td>\n</tr>\n<tr>\n<td>C. 物鏡</td>\n<td>樣本</td>\n<td>會聚透鏡</td>\n</tr>\n<tr>\n<td>D. 樣本</td>\n<td>會聚透鏡</td>\n<td>物鏡</td>\n</tr>\n</tbody>\n</table>",
   "file": "2024_P2_QU(CHI).md"
