   "text": "蒸發器、壓縮機、冷凝器和膨脹閥這些元件之中，何者是位於分體式空調機的室內單元內？\n\n- A. 膨脹閥、蒸發器和冷凝器\n- B. 膨脹閥和壓縮機\n- C. 蒸發器\n- D. 壓縮機",
   "html": "<p>蒸發器、壓縮機、冷凝器和膨脹閥這些元件之中，何者是位於分體式空調機的室內單元內？</p>\n<ul>\n<li>A. 膨脹閥、蒸發器和冷凝器</li>\n<li>B. 膨脹閥和壓縮機</li>\n<li>C. 蒸發器</li>\n<li>D. 壓縮機</li>\n</ul>",
   "file": "2024_P2_QU(CHI).md"
