   "html": "<p>一牆的熱傳送係數 (U-值) 取決於以下哪些因素？</p>\n<p>(1)　牆的厚度</p>\n<p>(2)　牆的總面積</p>\n<p>(3)　牆所用建築物料的導熱率</p>\n<ul>\n<li>A. 只有 (1) 和 (2)</li>\n<li>B. 只有 (1) 和 (3)</li>\n<li>C. 只有 (2) 和 (3)</li>\n<li>D. (1)、(2) 和 (3)</li>\n</ul>",
