   "text": "美玉的近點位於 68 cm。當她所戴矯視透鏡以鏡框固定在眼睛前 1.5 cm 處，則可清楚看到眼睛前 25 cm 的文字。她所戴矯視透鏡的焦強為多少？\n\n- A. +2.25 D\n- B. +2.75 D\n- C. +5.25 D\n- D. +5.75 D",
   "html": "<p>美玉的近點位於 68 cm。當她所戴矯視透鏡以鏡框固定在眼睛前 1.5 cm 處，則可清楚看到眼睛前 25 cm 的文字。她所戴矯視透鏡的焦強為多少？</p>\n<ul>\n<li>A. +2.25 D</li>\n<li>B. +2.75 D</li>\n<li>C. +5.25 D</li>\n<li>D. +5.75 D</li>\n</ul>",
   "file": "2024_P2_QU(CHI).md"
