   "text": "以下哪項有關光纖內窺鏡的敍述不正確？\n\n- A. 內窺鏡中每一光纖是以折射率較其稍低的物料包覆。\n- B. 光纖的直徑極幼細以確保其有可彎曲的彈性。\n- C. 照明和成像所用的是同一束光纖。\n- D. 成像的解像度受光纖的幼細度所限。",
   "html": "<p>以下哪項有關光纖內窺鏡的敍述不正確？</p>\n<ul>\n<li>A. 內窺鏡中每一光纖是以折射率較其稍低的物料包覆。</li>\n<li>B. 光纖的直徑極幼細以確保其有可彎曲的彈性。</li>\n<li>C. 照明和成像所用的是同一束光纖。</li>\n<li>D. 成像的解像度受光纖的幼細度所限。</li>\n</ul>",
   "file": "2024_P2_QU(CHI).md"
