   "text": "![電腦斷層造影 (CT) 成像](2024_P2_crops/q4_7.png)\n\n以下哪項有關上面電腦斷層造影 (CT) 成像的敍述正確？\n\n(1)　成像顯示出 X 射線被組織所吸收的程度。\n\n(2)　成像白色的區域顯示 X 射線最大程度的反射。\n\n(3)　X 射線被吸收的程度代表組織的不同功能。\n\n- A. 只有 (1)\n- B. 只有 (2)\n- C. 只有 (1) 和 (3)\n- D. 只有 (2) 和 (3)",
   "html": "<p><img alt=\"電腦斷層造影 (CT) 成像\" src=\"phys_2024_P2_crops/q4_7.png\" /></p>\n<p>以下哪項有關上面電腦斷層造影 (CT) 成像的敍述正確？</p>\n<p>(1)　成像顯示出 X 射線被組織所吸收的程度。</p>\n<p>(2)　成像白色的區域顯示 X 射線最大程度的反射。</p>\n<p>(3)　X 射線被吸收的程度代表組織的不同功能。</p>\n<ul>\n<li>A. 只有 (1)</li>\n<li>B. 只有 (2)</li>\n<li>C. 只有 (1) 和 (3)</li>\n<li>D. 只有 (2) 和 (3)</li>\n</ul>",
   "file": "2024_P2_QU(CHI).md"
