   "text": "以下哪項有關放射性核素成像 (RNI) 的敍述正確？\n\n(1)　RNI 的空間解像度比超聲掃描為佳。\n\n(2)　RNI 是採用發射 X 射線的放射性同位素。\n\n(3)　大部分 RNI 所用的放射性同位素為人工造成，而非天然存在的。\n\n- A. 只有 (1)\n- B. 只有 (3)\n- C. 只有 (1) 和 (2)\n- D. 只有 (2) 和 (3)",
   "html": "<p>以下哪項有關放射性核素成像 (RNI) 的敍述正確？</p>\n<p>(1)　RNI 的空間解像度比超聲掃描為佳。</p>\n<p>(2)　RNI 是採用發射 X 射線的放射性同位素。</p>\n<p>(3)　大部分 RNI 所用的放射性同位素為人工造成，而非天然存在的。</p>\n<ul>\n<li>A. 只有 (1)</li>\n<li>B. 只有 (3)</li>\n<li>C. 只有 (1) 和 (2)</li>\n<li>D. 只有 (2) 和 (3)</li>\n</ul>",
   "file": "2024_P2_QU(CHI).md"
