   "text": "(a)　α、β 和 γ 射線對人體有輻射危害性。根據輻射的貫穿能力和致電離能力，解釋為什麼 γ 射線會選作放射性核素成像 (RNI) 之用。（2 分）\n\n(b)　下面的衰變曲線代表 99mTc 的相對放射強度隨時間的變化（已作本底輻射修正）。\n\n![99mTc 衰變曲線](2024_P2_crops/q4_b.png)\n\n(i)　求 99mTc 的「物理半衰期」（以小時為單位）。（1 分）\n\n(ii)　在一項 RNI 探究中，製備一含有 99mTc 化合物的溶液，供有關病人注射。於 9:00 am 對該溶液進行校準時錄得溶液每 mL 含 550 MBq 放射性。如果病人安排於 11:00 am（即兩小時後）注射 600 MBq 的配方劑量，求需用溶液的體積，單位為 mL。（3 分）\n\n已知 99mTc 在人體內的「有效半衰期」為 4.8 小時。\n\n(iii)　求注射後經過 24 小時體內所剩劑量的百分數。（2 分）\n\n(iv)　根據 99mTc 的衰變曲線，99mTc 的相對放射強度經過 24 小時會下降至大約 6%。解釋 (iii) 所得結果與該數值（即約 6%）的差異。（2 分）\n\n---\n\n*試卷完 —*\n\n## 待人工核對\n\n本卷為第 2 層文字交貨（文字層可讀＋300dpi 原卷截圖）。現模型無影像輸入，未能對頁影像覆核，以下內容建議第 3 層精修時對頁核實：\n\n- 第 1.3 題：選項含根號（文字層失去根號符號），A／C／D 之確切寫法待對頁核實（本稿按物理重建為 √2v、2v、√3v）。\n- 第 1.5、1.6、1.8、2.1、2.3、2.4、2.7、3.1、3.2、3(a)、3(c)、4.7、4(b) 題：圖為 300dpi 原卷截圖（程式定位＋墨跡覆蓋率校驗；無視覺覆核，位置／範圍待 spot-check）；第 3 層再換成向量重繪。\n- 第 3.1 題：題幹未明示「如圖」，所附電熱平板爐／電磁爐圖（墨跡 34.7%）是否屬本題待對頁確認。\n- 第 4.4 題：聲強級改變之選項為分式公式，文字層分式結構亂碼，A–D 四選項以物理常式重建、待對頁逐字核實。\n- 各小題分數（1–3 分）以文字層辨識為準，待對頁核對。",
   "html": "<p>(a)　α、β 和 γ 射線對人體有輻射危害性。根據輻射的貫穿能力和致電離能力，解釋為什麼 γ 射線會選作放射性核素成像 (RNI) 之用。（2 分）</p>\n<p>(b)　下面的衰變曲線代表 99mTc 的相對放射強度隨時間的變化（已作本底輻射修正）。</p>\n<p><img alt=\"99mTc 衰變曲線\" src=\"phys_2024_P2_crops/q4_b.png\" /></p>\n<p>(i)　求 99mTc 的「物理半衰期」（以小時為單位）。（1 分）</p>\n<p>(ii)　在一項 RNI 探究中，製備一含有 99mTc 化合物的溶液，供有關病人注射。於 9:00 am 對該溶液進行校準時錄得溶液每 mL 含 550 MBq 放射性。如果病人安排於 11:00 am（即兩小時後）注射 600 MBq 的配方劑量，求需用溶液的體積，單位為 mL。（3 分）</p>\n<p>已知 99mTc 在人體內的「有效半衰期」為 4.8 小時。</p>\n<p>(iii)　求注射後經過 24 小時體內所剩劑量的百分數。（2 分）</p>\n<p>(iv)　根據 99mTc 的衰變曲線，99mTc 的相對放射強度經過 24 小時會下降至大約 6%。解釋 (iii) 所得結果與該數值（即約 6%）的差異。（2 分）</p>\n<hr />\n<p><em>試卷完 —</em></p>\n<h2>待人工核對</h2>\n<p>本卷為第 2 層文字交貨（文字層可讀＋300dpi 原卷截圖）。現模型無影像輸入，未能對頁影像覆核，以下內容建議第 3 層精修時對頁核實：</p>\n<ul>\n<li>第 1.3 題：選項含根號（文字層失去根號符號），A／C／D 之確切寫法待對頁核實（本稿按物理重建為 √2v、2v、√3v）。</li>\n<li>第 1.5、1.6、1.8、2.1、2.3、2.4、2.7、3.1、3.2、3(a)、3(c)、4.7、4(b) 題：圖為 300dpi 原卷截圖（程式定位＋墨跡覆蓋率校驗；無視覺覆核，位置／範圍待 spot-check）；第 3 層再換成向量重繪。</li>\n<li>第 3.1 題：題幹未明示「如圖」，所附電熱平板爐／電磁爐圖（墨跡 34.7%）是否屬本題待對頁確認。</li>\n<li>第 4.4 題：聲強級改變之選項為分式公式，文字層分式結構亂碼，A–D 四選項以物理常式重建、待對頁逐字核實。</li>\n<li>各小題分數（1–3 分）以文字層辨識為準，待對頁核對。</li>\n</ul>",
